export const questionsData = [
  // BAB 1: Langkah Keselamatan dalam Makmal
  { id: 101, chapter: 1, question: "Apakah fungsi utama kebuk wasap di dalam makmal?", options: ["A. Menyimpan bahan kimia radioaktif", "B. Menjalankan eksperimen yang membebaskan wap beracun", "C. Mensterilkan radas makmal", "D. Mengelakkan kontaminasi biologi"], correctAnswer: "B", explanation: "Kebuk wasap digunakan untuk menjalankan eksperimen yang melibatkan bahan mudah meruap, mudah terbakar, beracun, mengakis atau berbau." },
  { id: 102, chapter: 1, question: "Antara bahan berikut, yang manakah BOLEH dibuang terus ke dalam singki?", options: ["A. Sisa pepejal", "B. Pelarut organik", "C. Larutan natrium klorida", "D. Bahan sisa radioaktif"], correctAnswer: "C", explanation: "Larutan natrium klorida adalah bahan yang neutral dan mempunyai nilai pH antara 5 hingga 9, jadi ia selamat dibuang ke dalam singki." },
  { id: 103, chapter: 1, question: "Apakah jenis pemadam kebakaran yang sesuai untuk memadamkan kebakaran yang berpunca daripada peralatan elektrik?", options: ["A. Air", "B. Buih", "C. Karbon dioksida", "D. Selimut api"], correctAnswer: "C", explanation: "Karbon dioksida sesuai untuk memadamkan kebakaran peralatan elektrik kerana ia tidak mengalirkan elektrik." },
  { id: 104, chapter: 1, question: "Apakah peralatan perlindungan diri yang perlu digunakan untuk mengelakkan hidung daripada menghidu gas beracun?", options: ["A. Gogal", "B. Topeng muka", "C. Sarung tangan", "D. Baju makmal"], correctAnswer: "B", explanation: "Topeng muka melindungi hidung dan mulut daripada menghidu wap bahan kimia yang beracun dan berbau sengit." },
  { id: 105, chapter: 1, question: "Apakah warna label bagi alat pemadam kebakaran jenis buih?", options: ["A. Merah", "B. Biru", "C. Hitam", "D. Krim"], correctAnswer: "D", explanation: "Alat pemadam kebakaran jenis buih mempunyai label berwarna krim." },
  { id: 106, chapter: 1, question: "Peralatan manakah yang sesuai untuk mengelakkan kontaminasi semasa kerja-kerja mikrobiologi?", options: ["A. Kebuk wasap", "B. Kabinet aliran lamina", "C. Penyiram kecemasan", "D. Stesen pencuci mata"], correctAnswer: "B", explanation: "Kabinet aliran lamina digunakan untuk mengelakkan kontaminasi semasa kerja mikrobiologi dijalankan." },
  { id: 107, chapter: 1, question: "Bahan sisa biologi Kategori B merujuk kepada:", options: ["A. Sisa tajam seperti picagari", "B. Sisa tidak tajam seperti sarung tangan", "C. Bangkai haiwan", "D. Cecair seperti darah"], correctAnswer: "B", explanation: "Kategori B ialah sisa tidak tajam seperti sarung tangan, tisu, dan kapas kultur." },
  { id: 108, chapter: 1, question: "Bagaimanakah bangkai haiwan (Kategori C) perlu diuruskan sebelum dilupuskan?", options: ["A. Dibuang terus ke dalam tong sampah", "B. Dibungkus rapi dalam plastik biobahaya dan disejuk beku", "C. Dimasukkan ke dalam beg autoklaf", "D. Dicuci dan dikeringkan"], correctAnswer: "B", explanation: "Sisa haiwan atau bangkai (Kategori C) perlu dibalut rapi dan disimpan dalam peti sejuk beku sebelum dilupuskan." },
  { id: 109, chapter: 1, question: "Sekiranya bahan kimia terpercik ke mata, apakah tindakan pertama yang patut diambil?", options: ["A. Sapu mata dengan kain", "B. Cuci mata menggunakan stesen pencuci mata (eyewash station)", "C. Letakkan ais pada mata", "D. Biarkan sahaja sehingga kering"], correctAnswer: "B", explanation: "Tindakan serta-merta adalah dengan membilas mata di stesen pencuci mata dengan air mengalir sekurang-kurangnya 15 minit." },
  { id: 110, chapter: 1, question: "Apakah maksud kaedah PASS semasa menggunakan pemadam api?", options: ["A. Push, Aim, Squeeze, Sweep", "B. Pull, Aim, Squeeze, Sweep", "C. Pull, Attack, Squeeze, Stop", "D. Press, Aim, Sweep, Stop"], correctAnswer: "B", explanation: "PASS bermaksud Pull (tarik pin), Aim (halakan ke pangkal api), Squeeze (tekan pemicit), dan Sweep (layangkan dari kiri ke kanan)." },
  { id: 111, chapter: 1, question: "Merkuri dari termometer yang pecah perlu diuruskan dengan:", options: ["A. Menyapu dan membuangnya ke singki", "B. Menaburkan serbuk sulfur untuk menutupi tumpahan", "C. Mengelap dengan tisu basah", "D. Membiarkannya meruap"], correctAnswer: "B", explanation: "Serbuk sulfur digunakan untuk menutupi tumpahan merkuri kerana ia akan bertindak balas membentuk sebatian yang selamat." },
  { id: 112, chapter: 1, question: "Pemadam api serbuk kering mempunyai label berwarna:", options: ["A. Merah", "B. Hitam", "C. Biru", "D. Krim"], correctAnswer: "C", explanation: "Alat pemadam kebakaran serbuk kering dilabelkan dengan warna biru." },
  { id: 113, chapter: 1, question: "Bahan sisa yang mempunyai pH kurang dari 5 diklasifikasikan sebagai:", options: ["A. Selamat dibuang ke singki", "B. Sisa radioaktif", "C. Sisa biologi", "D. Bahan sisa yang tidak boleh dibuang ke singki"], correctAnswer: "D", explanation: "Bahan berasid dengan pH kurang dari 5 atau beralkali dengan pH lebih 9 dilarang sama sekali dibuang ke dalam singki." },
  { id: 114, chapter: 1, question: "Pakaian keselamatan manakah yang melindungi badan dari percikan bahan kimia?", options: ["A. Baju makmal", "B. Topeng muka", "C. Gogal", "D. Sarung tangan"], correctAnswer: "A", explanation: "Baju makmal direka panjang dan tahan bahan kimia untuk mengelakkan pakaian dan badan daripada terkena percikan." },
  { id: 115, chapter: 1, question: "Apakah tujuan autoklaf dalam pengurusan sisa biologi?", options: ["A. Membekukan sisa", "B. Mensterilkan dan membunuh mikrob berbahaya", "C. Mengisar sisa", "D. Mengeringkan sisa"], correctAnswer: "B", explanation: "Autoklaf menggunakan haba dan tekanan tinggi untuk mensteril dan membunuh bakteria/virus sebelum sisa biologi dilupuskan." },
  { id: 116, chapter: 1, question: "Pemadam api jenis apakah yang TIDAK sesuai untuk kebakaran minyak (Kelas B)?", options: ["A. Buih", "B. Serbuk kering", "C. Karbon dioksida", "D. Air"], correctAnswer: "D", explanation: "Air tidak boleh memadam kebakaran minyak kerana minyak akan timbul di atas air dan api akan terus merebak." },
  { id: 117, chapter: 1, question: "Selimut api (fire blanket) diperbuat daripada bahan apa?", options: ["A. Kain kapas", "B. Kain gentian kaca", "C. Kertas tahan api", "D. Plastik polimer"], correctAnswer: "B", explanation: "Selimut api selalunya diperbuat daripada gentian kaca yang tahan panas untuk memadamkan kebakaran kecil dengan menghalang oksigen." },
  { id: 118, chapter: 1, question: "Sisa tajam (Kategori A) perlu dibuang ke dalam:", options: ["A. Beg plastik biasa", "B. Tong biobahaya (bekas kuning)", "C. Singki", "D. Bekas sisa tajam khas (bekas khas tahan tusukan)"], correctAnswer: "D", explanation: "Sisa tajam (jarum, picagari, kaca) mestilah dimasukkan ke dalam bekas sisa tajam yang tidak mudah ditembus." },
  { id: 119, chapter: 1, question: "Bagaimanakah cara mencegah kebakaran semasa pemanasan alkohol di makmal?", options: ["A. Panaskan terus menggunakan penunu Bunsen", "B. Panaskan menggunakan kukus air (water bath)", "C. Jemur di bawah cahaya matahari", "D. Letakkan di tepi tingkap"], correctAnswer: "B", explanation: "Alkohol mudah terbakar, maka ia mesti dipanaskan menggunakan kukus air, bukan secara terus pada api." },
  { id: 120, chapter: 1, question: "Jika kebakaran mula merebak di makmal dan tidak terkawal, apakah tindakan yang BETUL?", options: ["A. Cuba memadamnya dengan air", "B. Menjerit dan panik", "C. Aktifkan penggera kebakaran dan keluar segera", "D. Bersembunyi di bawah meja"], correctAnswer: "C", explanation: "Jika api tidak terkawal, keselamatan nyawa adalah paling utama. Aktifkan penggera dan ikuti laluan kecemasan keluar." },

  // BAB 2: Bantuan Kecemasan
  { id: 201, chapter: 2, question: "Apakah situasi yang memerlukan tindakan Resusitasi Kardiopulmonari (CPR)?", options: ["A. Mangsa pengsan tetapi bernafas normal", "B. Mangsa luka berdarah", "C. Mangsa tidak bernafas dan tiada nadi", "D. Mangsa tercekik dan masih boleh batuk"], correctAnswer: "C", explanation: "CPR diberikan kepada individu yang tiada degupan jantung, tidak bernafas, atau tidak memberi sebarang tindak balas." },
  { id: 202, chapter: 2, question: "Apakah tujuan utama mampatan dada (chest compressions) dalam CPR?", options: ["A. Untuk membuka saluran pernafasan", "B. Untuk mengepam darah beroksigen ke seluruh badan", "C. Untuk memberi oksigen ke paru-paru", "D. Untuk menyedarkan mangsa"], correctAnswer: "B", explanation: "Mampatan dada membantu mengepam darah secara manual supaya darah beroksigen sampai ke otak dan organ penting." },
  { id: 203, chapter: 2, question: "Berapakah kedalaman mampatan dada yang disyorkan untuk CPR pada orang dewasa?", options: ["A. 1 - 2 cm", "B. Sekurang-kurangnya 5 cm", "C. 8 - 10 cm", "D. Tiada had kedalaman"], correctAnswer: "B", explanation: "Kedalaman mampatan dada bagi dewasa ialah sekurang-kurangnya 5 cm (maksimum 6 cm) supaya jantung dapat dipam dengan berkesan." },
  { id: 204, chapter: 2, question: "Berapakah kadar mampatan dada seminit semasa melakukan CPR?", options: ["A. 50 - 60 kali seminit", "B. 80 - 100 kali seminit", "C. 100 - 120 kali seminit", "D. 150 - 200 kali seminit"], correctAnswer: "C", explanation: "Kadar kelajuan mampatan dada yang betul adalah 100 hingga 120 kali seminit." },
  { id: 205, chapter: 2, question: "Apakah nisbah mampatan dada berbanding hembusan nafas dalam CPR?", options: ["A. 15 mampatan : 2 hembusan", "B. 30 mampatan : 2 hembusan", "C. 30 mampatan : 1 hembusan", "D. 10 mampatan : 2 hembusan"], correctAnswer: "B", explanation: "Nisbah yang disyorkan oleh pakar untuk CPR dewasa ialah 30 mampatan dada diikuti 2 kali hembusan." },
  { id: 206, chapter: 2, question: "Heimlich Maneuver digunakan untuk situasi:", options: ["A. Lelah (Asthma)", "B. Serangan jantung", "C. Mangsa tercekik saluran pernafasan", "D. Pengsan akibat strok haba"], correctAnswer: "C", explanation: "Heimlich Maneuver direka untuk menyingkirkan bendasing yang menghalang saluran pernafasan akibat tercekik." },
  { id: 207, chapter: 2, question: "Tanda-tanda mangsa memerlukan Heimlich Maneuver termasuklah:", options: ["A. Memegang leher dan tidak dapat bercakap", "B. Batuk dengan kuat", "C. Boleh menjerit meminta tolong", "D. Muntah dan loya"], correctAnswer: "A", explanation: "Tanda universal tercekik ialah memegang leher dengan kedua-dua tangan (universal choking sign), tidak boleh bercakap atau bernafas." },
  { id: 208, chapter: 2, question: "Di manakah kedudukan tangan penyelamat semasa melakukan Heimlich Maneuver pada orang dewasa?", options: ["A. Di bahagian atas dada", "B. Di bahagian leher", "C. Di antara pusat dan bawah tulang rusuk", "D. Di bawah perut"], correctAnswer: "C", explanation: "Penyelamat perlu meletakkan genggaman tangan di ruang antara pusat dan bahagian bawah tulang rusuk (abdomen)." },
  { id: 209, chapter: 2, question: "Apakah tindakan Heimlich Maneuver yang perlu dilakukan pada wanita hamil atau orang terlalu gemuk?", options: ["A. Tekanan dada (Chest thrusts)", "B. Tekanan perut (Abdominal thrusts)", "C. Tepukan dada (Chest blows)", "D. Tepukan punggung (Back blows)"], correctAnswer: "A", explanation: "Bagi wanita hamil atau individu obes, tekanan harus dialihkan ke bahagian dada (chest thrusts) dan bukannya perut." },
  { id: 210, chapter: 2, question: "Bagaimanakah Heimlich Maneuver dilakukan ke atas bayi berumur kurang 1 tahun?", options: ["A. Gabungan 5 tepukan belakang dan 5 tekanan dada", "B. Tekanan perut seperti orang dewasa", "C. Menggoncang badan bayi", "D. Memasukkan jari ke dalam mulut bayi dengan kasar"], correctAnswer: "A", explanation: "Untuk bayi, 5 tepukan belakang (back blows) berselang seli dengan 5 tekanan dada (chest thrusts) menggunakan 2 jari dilakukan." },
  { id: 211, chapter: 2, question: "Mengapakah mangsa tidak boleh ditinggalkan berseorangan jika tercekik?", options: ["A. Mangsa akan marah", "B. Kekurangan oksigen akan menyebabkan mangsa pengsan dalam beberapa minit", "C. Supaya mangsa boleh minum air", "D. Untuk menenangkan mangsa"], correctAnswer: "B", explanation: "Mangsa tercekik boleh kehilangan kesedaran (pengsan) dengan cepat jika saluran pernafasan tersumbat sepenuhnya, lalu menyebabkan kerosakan otak." },
  { id: 212, chapter: 2, question: "Apakah langkah pertama dalam CPR (Prinsip DRABC)?", options: ["A. D - Danger (Pastikan kawasan selamat)", "B. R - Response (Kejutkan mangsa)", "C. A - Airway (Buka saluran pernafasan)", "D. B - Breathing (Periksa pernafasan)"], correctAnswer: "A", explanation: "Langkah pertama ialah 'Danger', iaitu memastikan persekitaran selamat untuk penyelamat dan mangsa sebelum memulakan bantuan." },
  { id: 213, chapter: 2, question: "Bagaimanakah saluran pernafasan (Airway) mangsa dibuka sebelum hembusan CPR?", options: ["A. Dongakkan kepala dan angkat dagu mangsa", "B. Pusingkan kepala mangsa ke kiri", "C. Tutup hidung mangsa", "D. Angkat kaki mangsa"], correctAnswer: "A", explanation: "Teknik 'head-tilt, chin-lift' (dongak kepala, angkat dagu) dilakukan untuk mengangkat pangkal lidah daripada menghalang saluran pernafasan." },
  { id: 214, chapter: 2, question: "Adakah CPR boleh mengehidupkan semula jantung yang terhenti?", options: ["A. Ya, CPR adalah ubat untuk jantung", "B. Tidak, ia hanya mengekalkan aliran darah sehingga bantuan perubatan atau AED tiba", "C. Ya, ia menyambung urat yang putus", "D. Tidak, ia hanya mencuci darah"], correctAnswer: "B", explanation: "CPR bertujuan memanjangkan masa kecederaan otak supaya aliran darah yang beroksigen dapat berterusan sehingga alat AED atau ambulans tiba." },
  { id: 215, chapter: 2, question: "Jika anda keseorangan dan tercekik, apakah yang boleh anda lakukan?", options: ["A. Berlari mencari orang", "B. Melakukan Heimlich Maneuver pada diri sendiri dengan menekan perut pada hujung kerusi/meja", "C. Minum air dengan banyak", "D. Menjerit dengan kuat"], correctAnswer: "B", explanation: "Anda boleh melakukan 'Self-Heimlich' dengan membongkok dan menekan bahagian perut dengan kuat pada bucu objek kukuh seperti kerusi atau meja." },
  { id: 216, chapter: 2, question: "Semasa hembusan nafas CPR, kenapa dada mangsa perlu diperhatikan?", options: ["A. Untuk melihat sama ada dada naik dan turun (menandakan udara masuk)", "B. Untuk melihat degupan jantung", "C. Untuk memeriksa luka di dada", "D. Untuk memastikan tulang rusuk tidak patah"], correctAnswer: "A", explanation: "Jika dada naik dan turun semasa hembusan, ini menandakan saluran udara terbuka dan oksigen berjaya masuk ke dalam paru-paru mangsa." },
  { id: 217, chapter: 2, question: "Mangsa CPR perlu diletakkan dalam kedudukan yang bagaimana?", options: ["A. Meniarap di atas katil empuk", "B. Telentang di atas permukaan yang rata dan keras", "C. Mengiring ke kiri", "D. Bersandar pada dinding"], correctAnswer: "B", explanation: "Permukaan rata dan keras (seperti lantai) membolehkan mampatan dada menjadi efektif dengan menekan jantung ke arah tulang belakang." },
  { id: 218, chapter: 2, question: "Apakah tindakan seterusnya jika benda yang menyekat kerongkong mangsa berjaya dikeluarkan melalui Heimlich Maneuver?", options: ["A. Suruh mangsa berlari", "B. Bawa mangsa berjumpa doktor untuk pemeriksaan lanjut", "C. Berikan makanan pepejal", "D. Tinggalkan mangsa bersendirian"], correctAnswer: "B", explanation: "Mangsa perlu dibawa ke hospital untuk memastikan tiada kecederaan dalaman pada abdomen akibat tekanan atau kerosakan kerongkong." },
  { id: 219, chapter: 2, question: "Apakah punca utama seseorang itu boleh tercekik?", options: ["A. Makan sambil berbual, ketawa atau berjalan", "B. Minum air masak", "C. Mengunyah makanan dengan lumat", "D. Bernafas melalui hidung"], correctAnswer: "A", explanation: "Tercekik kerap berlaku apabila epiglotis tidak tertutup tepat pada masanya ketika seseorang makan sambil berbual atau ketawa." },
  { id: 220, chapter: 2, question: "Berapa lama ketiadaan oksigen ke otak akan menyebabkan kerosakan sel-sel otak secara kekal?", options: ["A. 1 minit", "B. 4 hingga 6 minit", "C. 30 minit", "D. 1 jam"], correctAnswer: "B", explanation: "Otak manusia hanya boleh bertahan selama lebih kurang 4-6 minit tanpa oksigen sebelum sel-sel mula mati secara kekal." },

  // BAB 3: Teknik Mengukur Parameter Kesihatan Badan
  { id: 301, chapter: 3, question: "Berapakah suhu badan normal manusia?", options: ["A. 35.0°C", "B. 36.9°C", "C. 38.5°C", "D. 40.0°C"], correctAnswer: "B", explanation: "Suhu badan normal manusia yang sihat adalah sekitar 36.9°C." },
  { id: 302, chapter: 3, question: "Alat apakah yang paling sesuai untuk mengukur suhu bayi pada bahagian dubur?", options: ["A. Termometer klinik", "B. Termometer makmal", "C. Termometer rektal", "D. Termometer inframerah"], correctAnswer: "C", explanation: "Termometer rektal direka khusus untuk mengukur suhu bayi melalui dubur kerana ia memberikan bacaan suhu teras badan yang paling tepat." },
  { id: 303, chapter: 3, question: "Mengapakah termometer klinik mempunyai pencerutan (kink) berhampiran bebuli merkuri?", options: ["A. Untuk mencantikkan reka bentuk", "B. Untuk mengelakkan merkuri turun semula dengan cepat sebelum suhu dibaca", "C. Untuk menjimatkan penggunaan merkuri", "D. Untuk memudahkan ia dipegang"], correctAnswer: "B", explanation: "Pencerutan (kink) menghalang merkuri daripada turun kembali ke bebuli dengan cepat, membolehkan suhu dibaca dengan tepat walaupun dikeluarkan dari mulut pesakit." },
  { id: 304, chapter: 3, question: "Apakah kelebihan termometer inframerah?", options: ["A. Murah dan ringkas", "B. Mengukur suhu dengan sentuhan yang kuat", "C. Mengukur suhu dengan cepat tanpa bersentuhan dengan pesakit", "D. Boleh menyukat suhu air mendidih"], correctAnswer: "C", explanation: "Termometer inframerah tidak memerlukan sentuhan fizikal, justeru dapat mengelakkan jangkitan silang dan mengukur suhu dengan sangat pantas." },
  { id: 305, chapter: 3, question: "Antara berikut, yang manakah titik nadi (pulse point) di pergelangan tangan?", options: ["A. Arteri karotid", "B. Arteri radialis", "C. Vena kava", "D. Aorta"], correctAnswer: "B", explanation: "Titik nadi di pergelangan tangan dipanggil arteri radialis, tempat denyutan jantung mudah dirasai." },
  { id: 306, chapter: 3, question: "Berapakah kadar denyutan nadi yang normal bagi orang dewasa yang sedang berehat?", options: ["A. 30 - 40 bpm", "B. 60 - 100 bpm", "C. 120 - 150 bpm", "D. 180 - 200 bpm"], correctAnswer: "B", explanation: "Kadar denyutan jantung atau nadi yang normal bagi dewasa yang sihat berehat adalah di antara 60 hingga 100 degupan seminit (bpm)." },
  { id: 307, chapter: 3, question: "Bagaimanakah jantina mempengaruhi kadar denyutan nadi?", options: ["A. Lelaki mempunyai kadar nadi lebih tinggi daripada perempuan", "B. Perempuan mempunyai kadar nadi lebih tinggi daripada lelaki", "C. Tiada perbezaan antara lelaki dan perempuan", "D. Nadi perempuan berhenti lebih cepat"], correctAnswer: "B", explanation: "Perempuan biasanya mempunyai saiz jantung yang sedikit kecil daripada lelaki, oleh itu jantung mereka perlu berdegup lebih kerap untuk mengepam isipadu darah yang sama." },
  { id: 308, chapter: 3, question: "Apakah alat yang digunakan untuk mengukur tekanan darah?", options: ["A. Elektrokardiogram (ECG)", "B. Sfigmomanometer", "C. Stetoskop", "D. Spektrometer"], correctAnswer: "B", explanation: "Sfigmomanometer adalah alat yang digunakan oleh pakar perubatan untuk mengukur tekanan darah (sistolik dan diastolik)." },
  { id: 309, chapter: 3, question: "Apakah yang dimaksudkan dengan tekanan darah sistolik?", options: ["A. Tekanan tertinggi apabila otot jantung mengecut", "B. Tekanan terendah apabila otot jantung berehat", "C. Tekanan darah dalam urat vena", "D. Tekanan darah di dalam paru-paru"], correctAnswer: "A", explanation: "Tekanan sistolik (bacaan atas) berlaku apabila jantung mengecut untuk mengepam darah ke seluruh badan, menghasilkan tekanan maksimum." },
  { id: 310, chapter: 3, question: "Bacaan tekanan darah yang normal adalah:", options: ["A. 140 / 90 mmHg", "B. 120 / 80 mmHg", "C. 90 / 60 mmHg", "D. 160 / 100 mmHg"], correctAnswer: "B", explanation: "Bacaan ideal bagi seorang individu sihat ialah 120 mmHg (sistolik) dan 80 mmHg (diastolik)." },
  { id: 311, chapter: 3, question: "Tekanan darah yang melebihi 140/90 mmHg diklasifikasikan sebagai:", options: ["A. Hipotensi (tekanan darah rendah)", "B. Hipertensi (tekanan darah tinggi)", "C. Normal", "D. Anemia"], correctAnswer: "B", explanation: "Bacaan 140/90 mmHg ke atas merupakan tanda hipertensi yang boleh membawa kepada risiko strok atau serangan jantung." },
  { id: 312, chapter: 3, question: "Apakah formula yang betul untuk mengira Indeks Jisim Badan (BMI)?", options: ["A. Jisim (kg) / Tinggi (cm)", "B. Jisim (kg) / Tinggi (m)", "C. Jisim (kg) / [Tinggi (m)]²", "D. Tinggi (m) / Jisim (kg)"], correctAnswer: "C", explanation: "Formula BMI ialah Jisim dibahagikan dengan (Tinggi didarab Tinggi dalam unit meter kuasa dua)." },
  { id: 313, chapter: 3, question: "Ali mempunyai jisim 65 kg dan tinggi 1.6 m. Berapakah nilai BMI Ali?", options: ["A. 20.3", "B. 25.4", "C. 30.1", "D. 40.6"], correctAnswer: "B", explanation: "BMI = 65 / (1.6 x 1.6) = 65 / 2.56 = 25.39. Beliau diklasifikasikan dalam kategori berlebihan jisim badan." },
  { id: 314, chapter: 3, question: "Seorang individu dengan nilai BMI 32.5 diklasifikasikan sebagai:", options: ["A. Kurang jisim badan", "B. Jisim badan normal", "C. Berlebihan jisim badan", "D. Obes"], correctAnswer: "D", explanation: "Nilai BMI 30.0 ke atas dikategorikan sebagai obesiti." },
  { id: 315, chapter: 3, question: "Apakah kesan negatif obesiti ke atas kesihatan manusia?", options: ["A. Sistem imun yang terlalu kuat", "B. Risiko mendapat diabetes melitus, penyakit kardiovaskular dan strok", "C. Mempunyai tulang yang lebih padat", "D. Tahan terhadap cuaca sejuk"], correctAnswer: "B", explanation: "Obesiti sering dikaitkan dengan pelbagai komplikasi kronik seperti sakit jantung, strok, dan kencing manis." },
  { id: 316, chapter: 3, question: "Langkah manakah yang paling baik untuk menurunkan jisim badan secara sihat?", options: ["A. Bersenam dengan kerap dan menjaga pemakanan seimbang", "B. Berlapar selama seminggu", "C. Mengambil ubat kurus yang tidak diiktiraf", "D. Tidur yang berlebihan"], correctAnswer: "A", explanation: "Mengurangkan pengambilan makanan berkalori tinggi dan bersenam (seperti kardio/berlari) adalah langkah yang selamat dan efektif." },
  { id: 317, chapter: 3, question: "Seorang atlet sukan mungkin mempunyai denyutan nadi rehat yang lebih rendah (cth: 50 bpm) kerana:", options: ["A. Dia mengalami sakit jantung", "B. Jantungnya lebih kuat dan efisien mengepam darah", "C. Jantungnya lemah", "D. Dia kurang darah"], correctAnswer: "B", explanation: "Atlet mempunyai otot jantung yang kuat, jadi ia dapat mengepam darah dengan isipadu yang besar dalam satu degupan." },
  { id: 318, chapter: 3, question: "Bilakah waktu terbaik untuk mengukur kadar denyutan nadi yang tepat?", options: ["A. Selepas berlari pantas", "B. Semasa dalam keadaan rehat atau baru bangun tidur", "C. Selepas makan banyak", "D. Semasa sedang marah"], correctAnswer: "B", explanation: "Nadi paling tepat diukur apabila badan berada dalam keadaan rehat supaya ia tidak dipengaruhi oleh senaman, tekanan, atau pencernaan." },
  { id: 319, chapter: 3, question: "Berapakah masa yang diperlukan untuk mengambil bacaan suhu badan menggunakan termometer klinik biasa (merkuri)?", options: ["A. 1 saat", "B. 2 hingga 3 minit", "C. 30 minit", "D. 1 jam"], correctAnswer: "B", explanation: "Bebuli termometer klinik perlu dibiarkan di bawah lidah atau ketiak selama kira-kira 2-3 minit supaya merkuri stabil." },
  { id: 320, chapter: 3, question: "Pengambilan makanan yang tinggi kandungan natrium (garam) boleh menyebabkan peningkatan bagi:", options: ["A. Suhu badan", "B. Kadar denyutan nadi", "C. Tekanan darah", "D. Indeks Jisim Badan (BMI)"], correctAnswer: "C", explanation: "Natrium mengikat air dalam saluran darah yang akan meningkatkan isipadu darah, lalu menyebabkan tekanan darah tinggi (hipertensi)." }
,
  // BAB 4: Teknologi Hijau
  { id: 401, chapter: 4, question: "Apakah yang dimaksudkan dengan Teknologi Hijau?", options: ["A. Penggunaan warna hijau dalam industri", "B. Pembangunan produk dan sistem untuk memelihara alam sekitar", "C. Penanaman lebih banyak pokok hijau di bandar", "D. Penggunaan bahan kimia dalam pertanian"], correctAnswer: "B", explanation: "Teknologi Hijau merujuk kepada pembangunan dan aplikasi produk, peralatan serta sistem untuk memelihara alam sekitar dan sumber semula jadi." },
  { id: 402, chapter: 4, question: "Antara berikut, yang manakah BUKAN tonggak utama Teknologi Hijau?", options: ["A. Tenaga", "B. Ekonomi", "C. Sosial", "D. Politik"], correctAnswer: "D", explanation: "Terdapat empat tonggak utama Teknologi Hijau: Tenaga, Alam Sekitar, Ekonomi, dan Sosial." },
  { id: 403, chapter: 4, question: "Apakah gas rumah hijau yang paling banyak menyumbang kepada pemanasan global akibat aktiviti manusia?", options: ["A. Oksigen", "B. Nitrogen", "C. Karbon dioksida", "D. Hidrogen"], correctAnswer: "C", explanation: "Karbon dioksida (CO2) adalah gas rumah hijau utama yang terhasil daripada pembakaran bahan api fosil." },
  { id: 404, chapter: 4, question: "Konsep 5R dalam pengurusan sisa pepejal bermaksud:", options: ["A. Refuse, Reduce, Reuse, Recycle, Recovery", "B. Refuse, Reduce, Reuse, Recycle, Repurpose", "C. Refuse, Reduce, Reuse, Repair, Recycle", "D. Replace, Reduce, Reuse, Recycle, Repurpose"], correctAnswer: "B", explanation: "Konsep 5R merangkumi Refuse (Tolak), Reduce (Kurangkan), Reuse (Guna semula), Recycle (Kitar semula), dan Repurpose (Guna untuk tujuan lain)." },
  { id: 405, chapter: 4, question: "Apakah kebaikan menggunakan baja kompos berbanding baja kimia sintetik?", options: ["A. Mencemarkan air bawah tanah", "B. Mengurangkan pembuangan sisa organik dan menyuburkan tanah", "C. Membunuh mikrob berfaedah dalam tanah", "D. Mengurangkan hasil tanaman"], correctAnswer: "B", explanation: "Baja kompos diperbuat daripada sisa organik, justeru ia mengurangkan sisa di tapak pelupusan dan mengekalkan kesuburan tanah secara semula jadi." },
  { id: 406, chapter: 4, question: "Tenaga boleh baharu merujuk kepada:", options: ["A. Tenaga yang akan kehabisan seperti arang batu", "B. Tenaga yang boleh dijana secara berterusan seperti solar dan angin", "C. Tenaga nuklear", "D. Tenaga daripada petroleum"], correctAnswer: "B", explanation: "Tenaga boleh baharu sentiasa ada dan boleh diisi semula secara semula jadi." },
  { id: 407, chapter: 4, question: "Apakah fungsi utama kenderaan elektrik (EV) dalam konteks Teknologi Hijau?", options: ["A. Menggunakan petrol dengan lebih efisien", "B. Menghasilkan bunyi yang kuat", "C. Mengurangkan pembebasan gas karbon monoksida dan karbon dioksida", "D. Menambahkan jerebu"], correctAnswer: "C", explanation: "EV tidak menggunakan bahan api fosil dan tidak membebaskan asap ekzos, sekali gus mengurangkan pencemaran udara." },
  { id: 408, chapter: 4, question: "Proses merawat air sisa kumbahan menggunakan mikroorganisma adalah satu contoh aplikasi Teknologi Hijau dalam sektor:", options: ["A. Tenaga", "B. Pengangkutan", "C. Pengurusan Sisa dan Air Sisa", "D. Pertanian"], correctAnswer: "C", explanation: "Rawatan air sisa menggunakan mikrob (rawatan biologi) merupakan penyelesaian lestari di bawah sektor Pengurusan Sisa dan Air Sisa." },
  { id: 409, chapter: 4, question: "Apakah yang dimaksudkan dengan 'Jejak Karbon' (Carbon Footprint)?", options: ["A. Kesan tapak kaki pada tanah gambut", "B. Jumlah gas rumah hijau yang dibebaskan oleh aktiviti manusia", "C. Jumlah oksigen yang diserap oleh tumbuhan", "D. Penggunaan bahan berasaskan karbon dalam industri"], correctAnswer: "B", explanation: "Jejak karbon mengukur jumlah keseluruhan gas rumah hijau (khususnya karbon dioksida) yang dihasilkan oleh aktiviti seseorang individu atau organisasi." },
  { id: 410, chapter: 4, question: "Amalan manakah yang dapat mengurangkan jejak karbon individu?", options: ["A. Memandu kereta bersendirian ke tempat kerja", "B. Menggunakan beg plastik untuk membelibelah", "C. Berkongsi kereta (carpool) atau menaiki pengangkutan awam", "D. Membiarkan lampu terpasang walaupun tidak digunakan"], correctAnswer: "C", explanation: "Berkongsi kereta atau menaiki bas/LRT mengurangkan bilangan kenderaan di jalan raya, sekaligus mengurangkan pelepasan karbon." },
  { id: 411, chapter: 4, question: "Mengapakah gas metana (CH4) berbahaya kepada alam sekitar?", options: ["A. Ia tidak berbau", "B. Ia menyebabkan hujan asid", "C. Ia merupakan gas rumah hijau yang sangat kuat memerangkap haba", "D. Ia menipiskan lapisan ozon"], correctAnswer: "C", explanation: "Metana mempunyai potensi pemanasan global (GWP) yang jauh lebih tinggi berbanding karbon dioksida." },
  { id: 412, chapter: 4, question: "Dalam sektor perhutanan, apakah langkah pemeliharaan yang selari dengan Teknologi Hijau?", options: ["A. Pembalakan haram", "B. Penyahhutanan (deforestation) secara besar-besaran", "C. Penanaman semula pokok dan pewartaan hutan simpan", "D. Pembakaran terbuka untuk pertanian"], correctAnswer: "C", explanation: "Menanam semula pokok (penghutanan semula) mengembalikan ekosistem dan mengekalkan penyerapan karbon dioksida." },
  { id: 413, chapter: 4, question: "Apakah istilah untuk reka bentuk bangunan yang memaksimumkan pencahayaan semula jadi dan pengudaraan untuk menjimatkan elektrik?", options: ["A. Bangunan pintar", "B. Bangunan Hijau (Green Building)", "C. Bangunan warisan", "D. Bangunan modular"], correctAnswer: "B", explanation: "Bangunan Hijau direka untuk menjadi cekap tenaga, air, dan sumber, serta mesra alam sekitar." },
  { id: 414, chapter: 4, question: "Apakah masalah utama dengan penggunaan plastik pakai buang?", options: ["A. Mudah koyak", "B. Terlalu ringan", "C. Tidak terbiodegradasi dan mencemarkan laut", "D. Mudah terbakar"], correctAnswer: "C", explanation: "Plastik sintetik tidak dapat diurai oleh bakteria, menyebabkan ia terkumpul di alam sekitar selama beratus-ratus tahun." },
  { id: 415, chapter: 4, question: "Biomassa ialah satu contoh sumber tenaga boleh baharu. Daripada manakah biomassa diperoleh?", options: ["A. Sisa tumbuhan, najis haiwan, dan sisa pertanian", "B. Cahaya matahari", "C. Aliran air sungai", "D. Angin kencang"], correctAnswer: "A", explanation: "Biomassa adalah bahan organik yang boleh dibakar atau diproses untuk menghasilkan bahan api." },
  { id: 416, chapter: 4, question: "Apakah tindakan 'Repurpose' (Guna untuk tujuan lain) dalam konsep 5R?", options: ["A. Menghantar kaca ke kilang kitar semula", "B. Menolak penggunaan straw plastik", "C. Menggunakan tayar lama sebagai pasu bunga", "D. Mengurangkan pembelian baju baru"], correctAnswer: "C", explanation: "Repurpose bermakna mengubah suai barangan terbuang menjadi sesuatu yang baru dan berguna, contohnya tayar sebagai pasu." },
  { id: 417, chapter: 4, question: "Kaedah kawalan biologi dalam pertanian bertujuan untuk:", options: ["A. Membunuh semua serangga di ladang", "B. Menggunakan pemangsa semula jadi untuk mengawal populasi perosak tanpa racun kimia", "C. Menghasilkan tanaman ubah suai genetik (GMO)", "D. Menggunakan jentera automatik"], correctAnswer: "B", explanation: "Kawalan biologi (cth: burung hantu makan tikus ladang) adalah mesra alam kerana ia tidak menggunakan racun kimia yang mencemarkan tanah." },
  { id: 418, chapter: 4, question: "Hujan asid terhasil akibat pembebasan gas apa ke atmosfera?", options: ["A. Sulfur dioksida dan nitrogen dioksida", "B. Oksigen dan karbon dioksida", "C. Metana dan hidrogen", "D. Klorofluorokarbon (CFC)"], correctAnswer: "A", explanation: "Sulfur dioksida (SO2) dan oksida nitrogen (NOx) bertindak balas dengan wap air untuk membentuk hujan asid yang merosakkan tanaman dan infrastruktur." },
  { id: 419, chapter: 4, question: "Apakah bahan ganti bagi polistirena yang lebih mesra alam untuk pembungkusan makanan?", options: ["A. Beg plastik nilon", "B. Bekas kaca berat", "C. Bekas makanan berasaskan hampas tebu atau kertas", "D. Kertas aluminium tebal"], correctAnswer: "C", explanation: "Bekas biodegradasi (seperti hampas tebu) mudah terurai di alam semula jadi berbanding polistirena." },
  { id: 420, chapter: 4, question: "Bagaimanakah tenaga hidroelektrik dijana?", options: ["A. Pembakaran arang batu untuk memanaskan air", "B. Penggunaan panel solar di atas air", "C. Menggunakan aliran air yang deras dari empangan untuk memutarkan turbin", "D. Kincir angin di tepi pantai"], correctAnswer: "C", explanation: "Kuasa hidro menggunakan tenaga kinetik air untuk memutar turbin yang disambung kepada penjana elektrik." },

  // BAB 5: Genetik
  { id: 501, chapter: 5, question: "Di manakah letaknya kromosom di dalam sel?", options: ["A. Sitoplasma", "B. Mitokondria", "C. Nukleus", "D. Membran sel"], correctAnswer: "C", explanation: "Kromosom berada di dalam nukleus dan mengandungi maklumat genetik (DNA)." },
  { id: 502, chapter: 5, question: "Berapakah bilangan kromosom di dalam sel soma (sel badan) manusia yang normal?", options: ["A. 23", "B. 46", "C. 44", "D. 2"], correctAnswer: "B", explanation: "Sel soma manusia mempunyai 46 kromosom (23 pasang), manakala sel gamet hanya mempunyai 23 kromosom." },
  { id: 503, chapter: 5, question: "Apakah proses pembahagian sel yang menghasilkan gamet (sperma dan ovum)?", options: ["A. Mitosis", "B. Meiosis", "C. Mutasi", "D. Kloning"], correctAnswer: "B", explanation: "Meiosis berlaku dalam organ pembiakan (testis/ovari) untuk menghasilkan sel anak (gamet) yang haploid." },
  { id: 504, chapter: 5, question: "Apakah kepentingan Mitosis kepada organisma?", options: ["A. Menghasilkan sel pembiakan", "B. Menyebabkan variasi genetik", "C. Untuk pertumbuhan dan menggantikan sel-sel yang rosak", "D. Membuang bahan kumuh"], correctAnswer: "C", explanation: "Mitosis menghasilkan sel-sel baharu yang seiras untuk membesarkan tisu (pertumbuhan) atau membaiki luka." },
  { id: 505, chapter: 5, question: "Dalam pembahagian meiosis, satu sel induk akan menghasilkan berapa sel anak?", options: ["A. 2", "B. 4", "C. 8", "D. Tiada sel dihasilkan"], correctAnswer: "B", explanation: "Meiosis melibatkan dua peringkat pembahagian sel berturut-turut, lalu menghasilkan 4 sel anak yang haploid." },
  { id: 506, chapter: 5, question: "Proses pindah silang (crossing over) yang menyebabkan variasi berlaku pada peringkat:", options: ["A. Mitosis", "B. Metafasa", "C. Profasa I dalam Meiosis", "D. Telofasa II"], correctAnswer: "C", explanation: "Semasa Profasa I dalam Meiosis, kromosom homolog bertukar-tukar segmen genetik." },
  { id: 507, chapter: 5, question: "Kromosom seks manakah yang menentukan jantina lelaki pada manusia?", options: ["A. XX", "B. XY", "C. YY", "D. XO"], correctAnswer: "B", explanation: "Lelaki mempunyai sepasang kromosom seks XY, manakala perempuan mempunyai XX." },
  { id: 508, chapter: 5, question: "Siapakah Bapa Genetik yang memperkenalkan Hukum Pewarisan melalui kajian kacang pea?", options: ["A. Charles Darwin", "B. Albert Einstein", "C. Gregor Mendel", "D. Louis Pasteur"], correctAnswer: "C", explanation: "Gregor Mendel membuat eksperimen dengan kacang pea dan merumuskan prinsip pewarisan trait genetik." },
  { id: 509, chapter: 5, question: "Individu dengan Sindrom Down mempunyai kromosom tambahan pada set kromosom yang ke berapa?", options: ["A. 13", "B. 18", "C. 21", "D. 23"], correctAnswer: "C", explanation: "Sindrom Down disebabkan oleh kehadiran 3 kromosom (Trisomi) pada pasangan kromosom ke-21." },
  { id: 510, chapter: 5, question: "Sifat rambut kerinting adalah trait dominan. Jika seorang ayah (homozigot dominan) dan ibu (homozigot resesif - rambut lurus) mendapat anak, apakah kemungkinan anak mereka berambut lurus?", options: ["A. 0%", "B. 25%", "C. 50%", "D. 100%"], correctAnswer: "A", explanation: "Oleh kerana bapa adalah homozigot dominan (RR), semua anak akan mewarisi alel dominan (R) dan semuanya akan berambut kerinting (Rr)." },
  { id: 511, chapter: 5, question: "Penyakit keturunan hemofilia (darah lambat membeku) disebabkan oleh gen mutan resesif yang terangkai pada kromosom:", options: ["A. Autosom", "B. Kromosom X", "C. Kromosom Y", "D. Mitokondria"], correctAnswer: "B", explanation: "Hemofilia ialah penyakit terangkai kromosom X. Lelaki lebih mudah menghidapnya kerana mereka hanya mempunyai satu kromosom X." },
  { id: 512, chapter: 5, question: "Mutasi gen bermaksud perubahan pada struktur bahan genetik. Antara berikut, manakah contoh mutasi gen?", options: ["A. Sindrom Klinefelter", "B. Albinisme (Balaran)", "C. Sindrom Down", "D. Sindrom Turner"], correctAnswer: "B", explanation: "Albinisme ialah mutasi pada gen yang mengawal pengeluaran melanin pigmen kulit. Sindrom-sindrom lain adalah mutasi kromosom." },
  { id: 513, chapter: 5, question: "Apakah yang dimaksudkan dengan mutasi yang berlaku akibat faktor persekitaran seperti sinaran radioaktif?", options: ["A. Mutasi spontan", "B. Mutasi teraruh (induced mutation)", "C. Mutasi kromosom", "D. Pindah silang"], correctAnswer: "B", explanation: "Faktor luaran seperti radioaktif dan sinar ultraungu (UV) yang menyebabkan mutasi dipanggil mutagen." },
  { id: 514, chapter: 5, question: "Teknologi pengklonan melibatkan pemindahan nukleus daripada ________ ke dalam ovum yang telah dibuang nukleusnya.", options: ["A. Sel gamet sperma", "B. Sel soma", "C. Sel darah merah", "D. Bakteria"], correctAnswer: "B", explanation: "Dalam pengklonan (cth. biri-biri Dolly), nukleus diploid sel soma digunakan untuk menggantikan nukleus haploid ovum." },
  { id: 515, chapter: 5, question: "Apakah kebaikan menghasilkan tanaman Ubah Suai Genetik (GMO)?", options: ["A. Tanaman cepat mati", "B. Memerlukan lebih banyak racun", "C. Meningkatkan daya tahan terhadap penyakit dan serangga perosak", "D. Mengurangkan hasil tanaman"], correctAnswer: "C", explanation: "Tanaman GMO direka bentuk untuk rintang terhadap penyakit atau iklim, lantas meningkatkan produktiviti pertanian." },
  { id: 516, chapter: 5, question: "Berapakah bilangan kromosom pada seseorang yang menghidap Sindrom Klinefelter (lelaki XXY)?", options: ["A. 45", "B. 46", "C. 47", "D. 48"], correctAnswer: "C", explanation: "Penghidap Sindrom Klinefelter mempunyai kromosom seks lebihan (XXY), menjadikan jumlah kromosomnya 47." },
  { id: 517, chapter: 5, question: "Antara faktor mutasi (mutagen) berikut, yang manakah bersifat kimia?", options: ["A. Sinar X", "B. Formaldehid dan karsinogen dalam asap rokok", "C. Sinaran gamma", "D. Cahaya matahari terik"], correctAnswer: "B", explanation: "Mutagen kimia termasuklah tar rokok, benzena, formaldehid, dan beberapa pengawet makanan sintetik." },
  { id: 518, chapter: 5, question: "Kariotip ialah ujian profil kromosom. Bagaimanakah kromosom disusun dalam kariotip?", options: ["A. Mengikut warna", "B. Daripada pasangan kromosom terpanjang hingga terpendek", "C. Secara rawak", "D. Mengikut abjad nama gen"], correctAnswer: "B", explanation: "Kariotip menyusun pasangan kromosom homolog berdasarkan saiz dari terbesar kepada terkecil, dan akhirnya pasangan kromosom seks." },
  { id: 519, chapter: 5, question: "Apakah gen dominan?", options: ["A. Gen yang hanya wujud pada lelaki", "B. Gen yang akan sentiasa mempamerkan ciri-cirinya walaupun hadir berpasangan dengan gen resesif", "C. Gen yang lemah dan tersembunyi", "D. Gen yang menyebabkan penyakit"], correctAnswer: "B", explanation: "Alel dominan (cth. Tinggi - T) sentiasa menonjol. Alel resesif (Rendah - t) hanya menonjol jika ia homozigot resesif (tt)." },
  { id: 520, chapter: 5, question: "Seorang lelaki buta warna mempunyai genotip:", options: ["A. XY", "B. X^b Y", "C. XX^b", "D. X^B Y"], correctAnswer: "B", explanation: "Buta warna ialah ciri gen resesif pada kromosom X. Oleh kerana lelaki ada satu kromosom X, gen buta warna resesif (b) akan terus menunjukkan kesannya (X^b Y)." },

  // BAB 6: Sokongan, Pergerakan dan Pertumbuhan
  { id: 601, chapter: 6, question: "Apakah fungsi utama rangka luar (eksoskeleton) pada serangga?", options: ["A. Untuk bernafas", "B. Menyokong berat badan dan melindungi organ dalaman serta mengelakkan kehilangan air", "C. Menyimpan makanan", "D. Menghasilkan sel darah"], correctAnswer: "B", explanation: "Rangka luar yang diperbuat daripada kitin berfungsi memberi sokongan fizikal dan mencegah badan daripada kekeringan." },
  { id: 602, chapter: 6, question: "Lintah dan cacing tanah disokong oleh jenis rangka apa?", options: ["A. Rangka luar", "B. Rangka dalam", "C. Rangka hidrostatik", "D. Tiada rangka"], correctAnswer: "C", explanation: "Bendalir dalam rongga badan yang memberikan tekanan pada dinding badan membentuk rangka hidrostatik." },
  { id: 603, chapter: 6, question: "Proses penanggalan kulit (rangka luar lama) pada haiwan invertebrata dipanggil:", options: ["A. Respirasi", "B. Ekdisis", "C. Evolusi", "D. Mutasi"], correctAnswer: "B", explanation: "Serangga atau krustasia perlu melakukan ekdisis untuk membesar kerana rangka luar mereka keras dan tidak boleh membesar." },
  { id: 604, chapter: 6, question: "Apakah fungsi lengkungan pektoral (bahu) pada rangka manusia?", options: ["A. Melindungi otak", "B. Menghubungkan tulang lengan dengan rangka paksi", "C. Menyokong berat badan semasa duduk", "D. Menghasilkan sperma"], correctAnswer: "B", explanation: "Lengkungan pektoral (tulang selangka dan skapula) menyambungkan lengan ke badan utama." },
  { id: 605, chapter: 6, question: "Otot pada lengan terdiri daripada otot bicep dan tricep. Otot-otot ini bertindak secara:", options: ["A. Sinergi (bekerjasama pada arah sama)", "B. Berantagonis (berlawanan)", "C. Pasif", "D. Graviti"], correctAnswer: "B", explanation: "Tindakan berantagonis bermaksud jika satu otot mengecut, pasangannya mesti mengendur untuk menghasilkan pergerakan." },
  { id: 606, chapter: 6, question: "Semasa membengkokkan lengan (mengangkat beban), apakah yang berlaku pada otot bicep dan tricep?", options: ["A. Bicep mengendur, tricep mengecut", "B. Bicep mengecut, tricep mengendur", "C. Kedua-duanya mengecut", "D. Kedua-duanya mengendur"], correctAnswer: "B", explanation: "Bicep menarik tulang lengan bawah ke atas (mengecut) manakala tricep mengendur." },
  { id: 607, chapter: 6, question: "Tisu yang menghubungkan antara otot dengan tulang dipanggil:", options: ["A. Ligamen", "B. Kartawan", "C. Rawan", "D. Tendon"], correctAnswer: "D", explanation: "Tendon adalah tisu penghubung yang kuat dan tidak kenyal yang memindahkan daya pengecutan otot kepada tulang." },
  { id: 608, chapter: 6, question: "Ligamen adalah tisu yang kuat, liat dan kenyal. Apakah fungsinya?", options: ["A. Menghubungkan tulang dengan tulang pada sendi", "B. Menghubungkan otot dengan tulang", "C. Melindungi otak", "D. Menghasilkan bendalir sinovial"], correctAnswer: "A", explanation: "Ligamen mengikat tulang bersama di sendi sambil membenarkan pergerakan yang fleksibel." },
  { id: 609, chapter: 6, question: "Di dalam sendi bergerak (seperti lutut), bendalir sinovial bertindak sebagai:", options: ["A. Gam untuk melekatkan tulang", "B. Pelincir untuk mengurangkan geseran antara tulang", "C. Penghasil sel darah putih", "D. Penyimpan lemak"], correctAnswer: "B", explanation: "Bendalir sinovial mengurangkan geseran dan menyerap hentakan pada rawan sendi semasa pergerakan." },
  { id: 610, chapter: 6, question: "Apakah bentuk graf lengkung pertumbuhan manusia yang normal?", options: ["A. Bentuk J", "B. Bentuk U", "C. Sigmoid (Bentuk S)", "D. Garis lurus yang mendatar"], correctAnswer: "C", explanation: "Lengkung pertumbuhan manusia normal berbentuk sigmoid, menunjukkan fasa lambat, cepat (eksponen), perlahan dan sifar." },
  { id: 611, chapter: 6, question: "Pertumbuhan serangga menunjukkan graf berbentuk:", options: ["A. Sigmoid", "B. Tangga (Step-like)", "C. Linear", "D. Bentuk loceng"], correctAnswer: "B", explanation: "Graf bentuk tangga berlaku kerana pertumbuhan serangga terhenti seketika semasa proses ekdisis, sebelum membesar dengan pantas." },
  { id: 612, chapter: 6, question: "Apakah tisu fleksibel dan bertindak sebagai kusyen penyerap hentakan di hujung tulang panjang?", options: ["A. Ligamen", "B. Tendon", "C. Rawan (Cartilage)", "D. Saraf"], correctAnswer: "C", explanation: "Rawan adalah tisu tisu penyambung yang licin dan elastik yang melindungi hujung tulang daripada bergesel." },
  { id: 613, chapter: 6, question: "Pada peringkat manakah kadar pertumbuhan manusia adalah paling pesat selain dari peringkat bayi?", options: ["A. Kanak-kanak (3 - 10 tahun)", "B. Remaja (akil baligh, 12 - 15 tahun)", "C. Dewasa awal (25 - 30 tahun)", "D. Tua (60 tahun ke atas)"], correctAnswer: "B", explanation: "Semasa akil baligh, kadar metabolisme dan rembesan hormon memuncak, menyebabkan lonjakan pertumbuhan (growth spurt)." },
  { id: 614, chapter: 6, question: "Burung mempunyai ciri penyesuaian khusus pada rangkanya untuk memudahkan penerbangan, iaitu:", options: ["A. Tulang yang berongga dan ringan", "B. Tulang yang sangat berat dan padat", "C. Cangkerang luar pelindung", "D. Tiada tulang belakang"], correctAnswer: "A", explanation: "Tulang pneumatik yang berongga mengurangkan berat badan burung, manakala tulang sternum yang besar menjadi tempat lekatan otot penerbangan." },
  { id: 615, chapter: 6, question: "Sendi engsel (hinge joint) hanya membenarkan pergerakan pada satu satah (180 darjah). Contoh sendi engsel pada manusia ialah:", options: ["A. Sendi bahu", "B. Sendi lutut dan siku", "C. Sendi leher", "D. Sendi tengkorak"], correctAnswer: "B", explanation: "Lutut dan siku berfungsi seperti engsel pintu yang hanya membenarkan lengan/kaki dibengkok dan diluruskan." },
  { id: 616, chapter: 6, question: "Kekurangan kalsium dan fosforus dalam diet berpanjangan, terutamanya pada wanita lebih tua, boleh menyebabkan penyakit:", options: ["A. Osteoporosis (Tulang rapuh)", "B. Diabetes", "C. Skurvi", "D. Hemofilia"], correctAnswer: "A", explanation: "Osteoporosis menjadikan tulang poros dan rapuh, menjadikannya mudah patah akibat jisim tulang yang merosot." },
  { id: 617, chapter: 6, question: "Penyakit di mana sendi mengalami keradangan, bengkak, dan sakit semasa pergerakan dipanggil:", options: ["A. Skoliosis", "B. Arthritis (Radang sendi)", "C. Leukemia", "D. Asma"], correctAnswer: "B", explanation: "Arthritis sering berlaku akibat penipisan rawan pada hujung tulang sendi." },
  { id: 618, chapter: 6, question: "Haiwan akuatik seperti paus tidak mempunyai rangka kaki yang kuat kerana:", options: ["A. Daya apungan air menyokong sebahagian besar berat badannya", "B. Paus adalah haiwan invertebrata", "C. Tulangnya diperbuat daripada jeli", "D. Paus berenang menggunakan tentakel"], correctAnswer: "A", explanation: "Air memberikan sokongan luar dalam bentuk daya apungan, jadi mamalia marin besar tidak memerlukan rangka tungkai yang kuat untuk menyokong berat badan." },
  { id: 619, chapter: 6, question: "Bentuk badan cacing tanah yang panjang dan bersegmen disokong oleh tekanan bendalir. Bagaimanakah cacing tanah bergerak?", options: ["A. Mengepakkan sayap", "B. Tindakan otot membujur dan otot lingkar secara berantagonis pada rangka hidrostatik", "C. Berenang", "D. Menggelongsor atas lendir tanpa bantuan otot"], correctAnswer: "B", explanation: "Pengecutan otot lingkar menjadikan cacing panjang dan kurus, manakala pengecutan otot membujur menjadikannya pendek dan tebal, menyebabkan pergerakan merayap." },
  { id: 620, chapter: 6, question: "Semasa pergerakan membengkokkan kaki, otot apakah yang mengecut?", options: ["A. Otot hamstring (belakang paha)", "B. Otot kuadrisep (depan paha)", "C. Otot tricep", "D. Otot rahang"], correctAnswer: "A", explanation: "Pada kaki, hamstring bertindak seperti bicep pada lengan; ia mengecut untuk membengkokkan lutut manakala kuadrisep mengendur." }

,
  // BAB 7: Koordinasi Badan
  { id: 701, chapter: 7, question: "Sistem koordinasi badan manusia dikawal oleh dua sistem utama iaitu:", options: ["A. Sistem Saraf dan Sistem Endokrin", "B. Sistem Saraf dan Sistem Pencernaan", "C. Sistem Otot dan Sistem Tulang", "D. Sistem Respirasi dan Sistem Peredaran Darah"], correctAnswer: "A", explanation: "Kedua-dua sistem saraf (saraf otak/tunjang) dan sistem endokrin (hormon) mengawal atur aktiviti dan gerak balas badan." },
  { id: 702, chapter: 7, question: "Hormon dirembeskan secara terus ke dalam:", options: ["A. Saluran darah", "B. Saluran limfa", "C. Pundi hempedu", "D. Perut"], correctAnswer: "A", explanation: "Kelenjar endokrin tidak mempunyai duktus, oleh itu hormon dirembes terus ke dalam aliran darah untuk dibawa ke organ sasaran." },
  { id: 703, chapter: 7, question: "Kelenjar manakah yang dikenali sebagai 'kelenjar induk' kerana ia mengawal kelenjar endokrin yang lain?", options: ["A. Tiroid", "B. Pankreas", "C. Kelenjar Pituitari", "D. Ovari"], correctAnswer: "C", explanation: "Kelenjar pituitari di dasar otak merembeskan hormon yang merangsang kelenjar lain seperti tiroid dan adrenal." },
  { id: 704, chapter: 7, question: "Apakah fungsi utama hormon insulin yang dirembeskan oleh pankreas?", options: ["A. Meningkatkan kadar metabolisme", "B. Mengawal atur (menurunkan) aras glukosa dalam darah", "C. Mempercepatkan degupan jantung", "D. Merangsang pertumbuhan tulang"], correctAnswer: "B", explanation: "Insulin menukarkan glukosa berlebihan di dalam darah kepada glikogen untuk disimpan di dalam hati dan otot." },
  { id: 705, chapter: 7, question: "Seseorang pesakit mendapati lehernya bengkak (goiter) dan kadar metabolismenya menurun. Kelenjar apakah yang mengalami masalah?", options: ["A. Adrenal", "B. Pankreas", "C. Kelenjar Tiroid", "D. Kelenjar Pituitari"], correctAnswer: "C", explanation: "Kelenjar tiroid merembes tiroksina yang mengawal metabolisme. Kekurangan iodin menyebabkan kelenjar ini membengkak (goiter)." },
  { id: 706, chapter: 7, question: "Hormon apakah yang disediakan oleh badan ketika menghadapi situasi cemas ('Lawan atau Lari')?", options: ["A. Estrogen", "B. Tiroksina", "C. Adrenalina", "D. Progesteron"], correctAnswer: "C", explanation: "Kelenjar adrenal merembes adrenalina untuk meningkatkan denyutan jantung, pernafasan dan bekalan glukosa ke otot sebagai persediaan." },
  { id: 707, chapter: 7, question: "Kekurangan hormon insulin akan menyebabkan penyakit:", options: ["A. Anemia", "B. Diabetes Melitus (Kencing manis)", "C. Goiter", "D. Kerdil"], correctAnswer: "B", explanation: "Tanpa insulin yang cukup, gula dalam darah tidak dapat diserap oleh sel dan dikeluarkan melalui air kencing (diabetes)." },
  { id: 708, chapter: 7, question: "Apakah dadah kategori depresan (penekan) yang memperlahankan aktiviti sistem saraf pusat?", options: ["A. Heroin dan Barbiturat", "B. Kafein dan Nikotin", "C. Amfetamin dan Kokain", "D. Ketamin dan LSD"], correctAnswer: "A", explanation: "Depresan memperlahankan tindak balas otak, menyebabkan rasa mengantuk dan mengurangkan kebimbangan." },
  { id: 709, chapter: 7, question: "Dadah yang menyebabkan pengguna melihat atau mendengar perkara yang tidak wujud tergolong dalam kumpulan:", options: ["A. Depresan", "B. Stimulan", "C. Inhalan", "D. Halusinogen"], correctAnswer: "D", explanation: "Halusinogen seperti LSD atau ganja mengubah persepsi minda dan menyebabkan halusinasi." },
  { id: 710, chapter: 7, question: "Pengambilan alkohol yang berlebihan secara berterusan boleh menyebabkan kerosakan teruk pada organ:", options: ["A. Paru-paru", "B. Hati (Sirosis hati)", "C. Kulit", "D. Pundi kencing"], correctAnswer: "B", explanation: "Alkohol diuraikan di dalam hati. Pengambilan berlebihan membebankan hati dan menyebabkan parut (sirosis) yang mematikan." },
  { id: 711, chapter: 7, question: "Hormon testosteron pada lelaki dirembeskan oleh kelenjar:", options: ["A. Pituitari", "B. Adrenal", "C. Testis", "D. Prostat"], correctAnswer: "C", explanation: "Testis menghasilkan testosteron yang mengawal perkembangan ciri-ciri seks sekunder lelaki dan penghasilan sperma." },
  { id: 712, chapter: 7, question: "Ovari merembeskan dua hormon utama pada wanita, iaitu:", options: ["A. Insulin dan Glukagon", "B. Estrogen dan Progesteron", "C. Testosteron dan Adrenalina", "D. Tiroksina dan ADH"], correctAnswer: "B", explanation: "Estrogen mengawal ciri seks wanita manakala progesteron menyediakan dinding uterus untuk penempelan embrio." },
  { id: 713, chapter: 7, question: "Bahan kimia yang disedut melalui hidung seperti gam dan cat pelarut dikenali sebagai:", options: ["A. Inhalan", "B. Stimulan", "C. Halusinogen", "D. Antibiotik"], correctAnswer: "A", explanation: "Inhalan membebaskan wap kimia yang disedut dan memusnahkan sel otak serta paru-paru dengan cepat." },
  { id: 714, chapter: 7, question: "Koordinasi badan manusia dipengaruhi oleh minda. Apakah yang dimaksudkan dengan 'Minda'?", options: ["A. Organ yang mengepam darah", "B. Pusat kawalan sistem pencernaan", "C. Keupayaan otak untuk berfikir, menaakul, dan mengawal emosi", "D. Cecair di dalam saraf tunjang"], correctAnswer: "C", explanation: "Minda bukanlah satu organ fizikal sebaliknya fungsi kesedaran mental otak yang melibatkan kecerdasan, ingatan, dan emosi." },
  { id: 715, chapter: 7, question: "Ketidakseimbangan hormon pertumbuhan dari kelenjar pituitari semasa kanak-kanak akan menyebabkan:", options: ["A. Keguguran rambut", "B. Kegergasian (Giantism) atau kekerdilan (Dwarfism)", "C. Buta warna", "D. Kerosakan gigi"], correctAnswer: "B", explanation: "Rembesan berlebihan hormon pertumbuhan menyebabkan kegergasian, manakala kekurangan merencatkan pertumbuhan (kerdil)." },
  { id: 716, chapter: 7, question: "Sistem saraf menghantar maklumat dalam bentuk:", options: ["A. Hormon dalam darah", "B. Impuls elektrik (saraf)", "C. Bahan kimia pencernaan", "D. Bunyi"], correctAnswer: "B", explanation: "Sistem saraf adalah sangat pantas kerana ia menggunakan isyarat impuls elektrik berbanding sistem endokrin yang menggunakan bahan kimia (hormon) yang lebih perlahan." },
  { id: 717, chapter: 7, question: "Amfetamin (seperti syabu) adalah sejenis dadah stimulan. Apakah kesannya kepada sistem saraf?", options: ["A. Melambatkan pernafasan", "B. Menidurkan pengguna", "C. Mempercepatkan kadar denyutan jantung dan aktiviti sistem saraf", "D. Menghilangkan halusinasi"], correctAnswer: "C", explanation: "Stimulan menjadikan seseorang hiperaktif, bertenaga sementara, tidak boleh tidur, dan sangat agresif." },
  { id: 718, chapter: 7, question: "Penyelarasan gerak balas secara spontan terhadap bahaya (cth: tarik tangan dari cerek panas) dikawal oleh:", options: ["A. Otak bahagian serebrum", "B. Tindakan luar kawal / refleks melalui saraf tunjang", "C. Kelenjar tiroid", "D. Pankreas"], correctAnswer: "B", explanation: "Tindakan refleks berlaku secara automatik tanpa berfikir, laluan impuls terus melintasi saraf tunjang untuk mengelakkan kecederaan." },
  { id: 719, chapter: 7, question: "Proprioceptor atau reseptor regangan berfungsi mengekalkan postur badan. Ia terdapat pada bahagian:", options: ["A. Mata dan telinga", "B. Otot, tendon, sendi dan ligamen", "C. Permukaan kulit", "D. Perut dan usus"], correctAnswer: "B", explanation: "Reseptor ini membolehkan manusia merasai kedudukan anggota badan dan mengimbangi postur walaupun mata tertutup (kinestesis)." },
  { id: 720, chapter: 7, question: "Mengapakah pesakit diabetes melitus sering mengalami rasa dahaga dan kerap kencing?", options: ["A. Kerana mereka kekurangan air", "B. Kandungan gula berlebihan menarik air dari sel keluar ke aliran darah lalu dikumuhkan di buah pinggang", "C. Insulin menyebabkan rasa dahaga", "D. Tekanan darah terlampau rendah"], correctAnswer: "B", explanation: "Apabila gula darah sangat tinggi, buah pinggang mengepam air untuk menyingkirkan glukosa tersebut, menyebabkan pesakit mengalami dehidrasi kronik." },

  // BAB 8: Unsur dan Bahan
  { id: 801, chapter: 8, question: "Bahan yang terdiri daripada satu jenis atom sahaja dikenali sebagai:", options: ["A. Sebatian", "B. Unsur", "C. Campuran", "D. Ion"], correctAnswer: "B", explanation: "Unsur ialah jirim paling ringkas (seperti emas, oksigen) yang tidak boleh dipecahkan lagi melalui kaedah kimia." },
  { id: 802, chapter: 8, question: "Molekul ialah partikel yang:", options: ["A. Bercas elektrik", "B. Terbina daripada sekurang-kurangnya dua atom yang bergabung secara kimia", "C. Boleh dilihat dengan mata kasar", "D. Terdapat hanya dalam benda hidup"], correctAnswer: "B", explanation: "Molekul boleh terdiri daripada atom yang sama (seperti O2) atau berlainan (seperti H2O)." },
  { id: 803, chapter: 8, question: "Dalam Jadual Berkala Unsur Moden, bagaimanakah unsur-unsur disusun?", options: ["A. Mengikut pertambahan jisim atom", "B. Mengikut warna", "C. Mengikut pertambahan nombor proton", "D. Mengikut saiz atom yang mengecil"], correctAnswer: "C", explanation: "Jadual moden disusun secara mendatar (Kala) berdasarkan bilangan proton di dalam nukleus atom." },
  { id: 804, chapter: 8, question: "Turus menegak dalam Jadual Berkala dikenali sebagai:", options: ["A. Kumpulan", "B. Kala", "C. Zon Logam", "D. Blok"], correctAnswer: "A", explanation: "Terdapat 18 Kumpulan. Unsur dalam kumpulan yang sama mempunyai ciri kimia (bilangan elektron valens) yang sama." },
  { id: 805, chapter: 8, question: "Natrium klorida (garam dapur) adalah bahan yang terdiri daripada gabungan:", options: ["A. Molekul organik", "B. Ion positif dan ion negatif", "C. Atom-atom lengai", "D. Unsur gas"], correctAnswer: "B", explanation: "Natrium klorida terbentuk apabila ion Natrium (Na+) tertarik kepada ion Klorida (Cl-)." },
  { id: 806, chapter: 8, question: "Atom akan membentuk ion bercas POSITIF apabila:", options: ["A. Menerima proton", "B. Membuang/menderma elektron", "C. Menerima elektron", "D. Membuang neutron"], correctAnswer: "B", explanation: "Logam (seperti Natrium) menderma elektron valensnya, mengakibatkan bilangan proton (positif) lebih banyak daripada elektron (negatif)." },
  { id: 807, chapter: 8, question: "Unsur yang berada di sebelah KANAN dalam Jadual Berkala kebanyakannya adalah:", options: ["A. Logam", "B. Separuh Logam (Metaloid)", "C. Bukan Logam", "D. Unsur Radioaktif"], correctAnswer: "C", explanation: "Kumpulan 15, 16, 17, dan 18 di sebelah kanan adalah unsur-unsur bukan logam (gas dan penebat)." },
  { id: 808, chapter: 8, question: "Isotop ialah atom-atom bagi unsur yang sama yang mempunyai:", options: ["A. Bilangan proton yang berbeza", "B. Bilangan proton sama tetapi bilangan neutron berbeza", "C. Bilangan elektron yang berbeza", "D. Sifat kimia yang berbeza"], correctAnswer: "B", explanation: "Isotop (contoh: Karbon-12, Karbon-14) berkongsi nombor proton yang sama tetapi beratnya (jisim) berbeza kerana beza bilangan neutron." },
  { id: 809, chapter: 8, question: "Karbon-14 adalah isotop radioaktif. Apakah kegunaan utamanya?", options: ["A. Membunuh sel kanser", "B. Menjana tenaga elektrik", "C. Menentukan usia bahan fosil dan artifak purba", "D. Mengawal tiroid"], correctAnswer: "C", explanation: "Penyusutan radioaktif Karbon-14 (pentarikhan karbon) digunakan oleh ahli arkeologi untuk menganggarkan umur sisa hidupan purba." },
  { id: 810, chapter: 8, question: "Kobalt-60 adalah isotop yang penting dalam bidang perubatan untuk:", options: ["A. Mensterilkan alat pembedahan", "B. Merawat penyakit kanser (Radioterapi)", "C. X-ray gigi", "D. Menajamkan penglihatan"], correctAnswer: "B", explanation: "Sinar gamma yang dipancarkan oleh Kobalt-60 sangat bertenaga dan digunakan untuk memusnahkan sel kanser dengan tepat." },
  { id: 811, chapter: 8, question: "Zarah subatom yang terdapat DI DALAM nukleus atom ialah:", options: ["A. Elektron sahaja", "B. Proton dan elektron", "C. Proton dan neutron", "D. Neutron sahaja"], correctAnswer: "C", explanation: "Nukleus di pusat atom mengandungi proton (bercas positif) dan neutron (neutral). Elektron mengorbit di sekeliling nukleus." },
  { id: 812, chapter: 8, question: "Unsur yang terletak dalam Kumpulan 18 dikenali sebagai Gas Nadir atau Gas Lengai kerana:", options: ["A. Ia sangat reaktif", "B. Ia mempunyai petala elektron luar yang penuh (stabil) dan tidak bertindak balas", "C. Ia mudah terbakar", "D. Ia sangat beracun"], correctAnswer: "B", explanation: "Gas nadir seperti Helium dan Neon sudah mencapai susunan elektron duplet/oktet yang stabil." },
  { id: 813, chapter: 8, question: "Sifat-sifat fizik logam secara amnya termasuklah:", options: ["A. Penebat elektrik", "B. Rapuh dan pudar", "C. Mulur, boleh ditempa, dan konduktor elektrik yang baik", "D. Takat lebur yang sangat rendah"], correctAnswer: "C", explanation: "Logam (seperti besi, kuprum) boleh dibentuk (ditempa), ditarik menjadi dawai (mulur), dan mengkonduksikan haba dan arus elektrik." },
  { id: 814, chapter: 8, question: "Unsur Fosforus-32 digunakan secara meluas dalam bidang apa?", options: ["A. Arkeologi", "B. Pertanian (Mengkaji penyerapan baja fosforus oleh tumbuhan)", "C. Perubatan (Mengkaji pengaliran darah)", "D. Industri nuklear"], correctAnswer: "B", explanation: "Fosforus-32 membolehkan saintis mengesan pergerakan unsur fosforus dari baja menembusi sistem akar tumbuhan." },
  { id: 815, chapter: 8, question: "Apabila unsur Fluorin (Kumpulan 17) menerima elektron, ia membentuk:", options: ["A. Kation bercas positif", "B. Anion bercas negatif (Ion Fluorida)", "C. Molekul gas", "D. Bahan pepejal emas"], correctAnswer: "B", explanation: "Bukan logam mencapai kestabilan dengan menerima elektron. Elektron bercas negatif, jadi ion terhasil (anion) juga bercas negatif." },
  { id: 816, chapter: 8, question: "Berapakah bilangan elektron maksimum yang boleh diisi dalam petala pertama (paling hampir dengan nukleus)?", options: ["A. 8", "B. 2", "C. 18", "D. 32"], correctAnswer: "B", explanation: "Susunan petala elektron atom: petala pertama boleh memuatkan 2 elektron, petala kedua 8 elektron." },
  { id: 817, chapter: 8, question: "Air tulen (H2O) dikelaskan sebagai sebatian kerana:", options: ["A. Ia adalah cecair jernih", "B. Ia terdiri daripada Hidrogen dan Oksigen yang terikat secara kimia pada nisbah tetap", "C. Boleh diasingkan menggunakan penurasan", "D. Tidak mengandungi bakteria"], correctAnswer: "B", explanation: "Sebatian terbentuk melalui tindak balas kimia unsur berlainan (H dan O), dan sifat air sangat berbeza daripada gas H2 dan gas O2." },
  { id: 818, chapter: 8, question: "Apakah kegunaan isotop Natrium-24 dalam industri?", options: ["A. Mengesan kebocoran paip air atau gas di bawah tanah", "B. Merawat penyakit tiroid", "C. Mencegah makanan cepat rosak", "D. Menghasilkan bateri kereta"], correctAnswer: "A", explanation: "Natrium-24 memancarkan sinaran yang boleh dikesan di atas tanah dengan alat pembilang Geiger-Muller tanpa perlu menggali keseluruhan paip." },
  { id: 819, chapter: 8, question: "Dalam sejarah perkembangan model atom, model 'Puding Plum' yang mencadangkan sfera bercas positif berserta elektron yang bertaburan dikemukakan oleh:", options: ["A. John Dalton", "B. J.J. Thomson", "C. Ernest Rutherford", "D. Neils Bohr"], correctAnswer: "B", explanation: "J.J Thomson menemui elektron dan membayangkan atom seperti kuih puding plum." },
  { id: 820, chapter: 8, question: "Campuran seperti air laut boleh diasingkan melalui kaedah fizikal. Proses pengasingan garam dari air laut dipanggil:", options: ["A. Pembakaran", "B. Peneutralan", "C. Penyejatan dan penghabluran", "D. Elektrolisis"], correctAnswer: "C", explanation: "Campuran tidak terikat secara kimia, jadi garam pepejal (hablur) boleh diperoleh apabila cecair air menyejat." },

  // BAB 9: Kimia Industri
  { id: 901, chapter: 9, question: "Aloi ialah campuran yang terbentuk apabila:", options: ["A. Dua cecair dicampurkan", "B. Logam utama dileburkan bersama-sama dengan logam atau bukan logam lain dalam peratusan tertentu", "C. Besi direndam di dalam asid", "D. Garam dilarutkan dalam air"], correctAnswer: "B", explanation: "Pengaloian melibatkan penambahan bendasing (atom asing) ke dalam kekisi logam tulen untuk mengubah sifatnya." },
  { id: 902, chapter: 9, question: "Tujuan utama menghasilkan aloi seperti keluli daripada besi tulen adalah untuk:", options: ["A. Menjadikannya lebih ringan", "B. Mengelakkan karat dan meningkatkan kekerasan", "C. Menjadikannya konduktor haba yang lemah", "D. Mencantikkan warna merah karat"], correctAnswer: "B", explanation: "Besi tulen lembut dan mudah berkarat. Penambahan karbon (membentuk keluli) menyusahkan lapisan atom tergelincir, menjadikannya keras." },
  { id: 903, chapter: 9, question: "Duit syiling warna emas selalunya diperbuat daripada Loyang. Loyang adalah aloi bagi campuran:", options: ["A. Kuprum dan Zink", "B. Kuprum dan Timah", "C. Besi dan Karbon", "D. Emas dan Perak"], correctAnswer: "A", explanation: "Loyang adalah campuran kuprum (utama) dan zink, ia lebih keras dari kuprum tulen dan rupa berkilat." },
  { id: 904, chapter: 9, question: "Kaca dibuat dengan memanaskan bahan mentah utamanya, iaitu silika pada suhu yang sangat tinggi. Silika diperoleh daripada:", options: ["A. Tanah liat (kaolin)", "B. Pasir", "C. Batu kapur", "D. Arang batu"], correctAnswer: "B", explanation: "Silika (silikon dioksida) banyak terdapat dalam pasir pantai putih." },
  { id: 905, chapter: 9, question: "Kaca borosilikat digunakan secara meluas di dalam makmal (contohnya bikar) dan peralatan memasak (seperti Pyrex) kerana ia:", options: ["A. Tidak boleh pecah jika terjatuh", "B. Tahan terhadap bahan kimia dan perubahan suhu yang mendadak", "C. Sangat murah dan lut sinar", "D. Mempunyai takat lebur rendah"], correctAnswer: "B", explanation: "Kaca borosilikat mengembang dengan minimum apabila dipanaskan, menjadikannya tidak retak apabila dituangkan cecair panas." }

,
  { id: 906, chapter: 9, question: "Seramik tradisional, seperti tembikar, dibuat daripada bahan tanah liat yang dikenali sebagai:", options: ["A. Silika", "B. Kaolin (Aluminium silikat)", "C. Pasir", "D. Bauksit"], correctAnswer: "B", explanation: "Kaolin adalah komponen utama tanah liat yang akan mengeras selepas melalui proses pembakaran pada suhu tinggi." },
  { id: 907, chapter: 9, question: "Apakah sifat utama seramik yang membolehkannya digunakan untuk membuat mangkuk pijar dan penebat litar elektrik berkuasa tinggi?", options: ["A. Konduktor haba yang baik", "B. Penebat haba dan elektrik yang sangat baik serta tahan haba tinggi", "C. Mudah lebur", "D. Boleh mengalirkan elektrik"], correctAnswer: "B", explanation: "Seramik tidak mengalirkan elektrik dan haba, dan ia mengekalkan strukturnya pada suhu yang mencairkan logam." },
  { id: 908, chapter: 9, question: "Kelemahan utama kaca dan seramik berbanding logam ialah:", options: ["A. Ia berkarat", "B. Ia tidak telus cahaya", "C. Ia rapuh dan mudah pecah apabila dihentak", "D. Ia sangat mahal"], correctAnswer: "C", explanation: "Kaca dan seramik tidak mulur dan tidak boleh ditempa; ia pecah berderai jika dikenakan daya mekanikal yang kuat." },
  { id: 909, chapter: 9, question: "Polimer adalah molekul rantaian panjang yang terbentuk daripada gabungan banyak molekul kecil. Molekul kecil ini dipanggil:", options: ["A. Isomer", "B. Monomer", "C. Ion", "D. Aloi"], correctAnswer: "B", explanation: "Proses pempolimeran menggabungkan beribu-ribu unit monomer yang berulang menjadi satu makromolekul polimer." },
  { id: 910, chapter: 9, question: "Antara berikut, yang manakah BUKAN contoh polimer semula jadi?", options: ["A. Getah asli", "B. Sutera", "C. Kanji", "D. Nilon (Plastik)"], correctAnswer: "D", explanation: "Nilon ialah polimer sintetik yang dihasilkan di kilang melalui produk petroleum, manakala yang lain terhasil dari tumbuhan/haiwan." },
  { id: 911, chapter: 9, question: "Apakah nama monomer bagi getah asli?", options: ["A. Etena", "B. Isoprena", "C. Glukosa", "D. Kloroetena"], correctAnswer: "B", explanation: "Susu getah (lateks) mengandungi molekul-molekul polimer poliisoprena (gabungan monomer isoprena)." },
  { id: 912, chapter: 9, question: "Tindakan mencampurkan asid urik (atau asid formik/asid asetik) ke dalam lateks cair (susu getah) akan menyebabkan lateks:", options: ["A. Menjadi lebih cair", "B. Mendidih", "C. Menggumpal (Membeku)", "D. Bertukar warna merah"], correctAnswer: "C", explanation: "Ion hidrogen dari asid meneutralkan cas negatif pada membran zarah getah, membolehkan zarah-zarah berlanggar, pecah, dan menggumpal." },
  { id: 913, chapter: 9, question: "Sifat getah asli ialah ia lembut dan kurang kenyal pada suhu tinggi. Untuk menjadikannya lebih kuat dan kenyal, ia dipanaskan dengan:", options: ["A. Karbon", "B. Oksigen", "C. Sulfur (Proses Pemvulkanan)", "D. Kalsium"], correctAnswer: "C", explanation: "Proses pemvulkanan menambah atom sulfur yang membentuk 'rangkai silang' (cross-links) antara rantai polimer getah." },
  { id: 914, chapter: 9, question: "Apakah kelebihan getah tervulkan (vulcanised rubber) berbanding getah asli?", options: ["A. Lebih rapuh", "B. Lebih kenyal, kuat, dan tahan haba tinggi", "C. Mudah larut dalam air", "D. Tidak boleh digunakan untuk membuat tayar"], correctAnswer: "B", explanation: "Rangkai silang sulfur menarik rantai polimer kembali ke kedudukan asal jika diregangkan (kenyal) dan mengelakkannya mencair pada cuaca panas." },
  { id: 915, chapter: 9, question: "Mengapakah larutan ammonia (alkali) ditambahkan ke dalam lateks yang baru ditoreh?", options: ["A. Untuk mengeraskan getah", "B. Untuk menjadikan getah lebih wangi", "C. Untuk mengelakkan penggumpalan awal dan membiarkan lateks kekal cair", "D. Untuk membersihkan getah"], correctAnswer: "C", explanation: "Ammonia meneutralkan asid laktik yang dihasilkan oleh bakteria dalam lateks, seterusnya menghalang lateks dari menggumpal sebelum dihantar ke kilang." },
  { id: 916, chapter: 9, question: "Gentian optik diperbuat daripada kaca silika ketulenan tinggi dan gentian polimer. Apakah fungsi utamanya?", options: ["A. Membuat cermin tingkap", "B. Menghantar data telekomunikasi berkelajuan tinggi dan imej perubatan (endoskopi) menggunakan pantulan cahaya", "C. Membuat baju tahan api", "D. Menyalurkan air"], correctAnswer: "B", explanation: "Gentian optik membimbing cahaya dengan pantulan dalam penuh, sesuai untuk internet dan kamera bedah mini." },
  { id: 917, chapter: 9, question: "Antara aloi berikut, yang manakah digunakan untuk membuat badan kapal terbang kerana ia ringan tetapi kuat?", options: ["A. Keluli nirkarat", "B. Gangsa", "C. Duralumin", "D. Piuter"], correctAnswer: "C", explanation: "Duralumin (Aloi bagi Aluminium) sangat ringan dan kuat, sesuai untuk aplikasi aeroangkasa." },
  { id: 918, chapter: 9, question: "Apakah kegunaan utama keluli nirkarat (stainless steel) yang dicampur dengan kromium dan nikel?", options: ["A. Membuat tayar kereta", "B. Membuat alatan pembedahan dan kutleri kerana ia tidak berkarat", "C. Membuat pasu bunga", "D. Membuat bateri"], correctAnswer: "B", explanation: "Kromium dan nikel membentuk lapisan pelindung yang nipis menghalang oksigen bertindak balas dengan besi." },
  { id: 919, chapter: 9, question: "Polietilena (PE) ialah sejenis polimer plastik sintetik. Ia sesuai digunakan untuk membuat:", options: ["A. Tayar lori berat", "B. Beg plastik dan botol minuman plastik", "C. Tingkap kalis peluru", "D. Pasu seramik"], correctAnswer: "B", explanation: "PE ialah plastik ringan, lut cahaya dan kalis air." },
  { id: 920, chapter: 9, question: "Bahan superkonduktor merupakan aloi berteknologi tinggi yang membolehkan:", options: ["A. Pengaliran arus elektrik tanpa sebarang rintangan (tiada kehilangan tenaga haba) pada suhu yang sangat rendah", "B. Elektrik dihentikan 100%", "C. Haba dibebaskan dengan cepat", "D. Pencairan besi"], correctAnswer: "A", explanation: "Superkonduktor (contoh aloi YBCO) digunakan dalam sistem pengimejan MRI dan kereta api Maglev." },

  // BAB 10: Kimia dalam Perubatan dan Kesihatan
  { id: 1001, chapter: 10, question: "Kaedah perubatan yang menggunakan haiwan atau tumbuhan (herba) tanpa pemprosesan kimia dikenali sebagai:", options: ["A. Perubatan Moden", "B. Perubatan Tradisional", "C. Perubatan Komplementari", "D. Perubatan Allopati"], correctAnswer: "B", explanation: "Perubatan tradisional diwarisi turun-temurun berlandaskan pengalaman menggunakan bahan semula jadi." },
  { id: 1002, chapter: 10, question: "Tumbuhan manakah yang sering digunakan dalam perubatan tradisional untuk melegakan masalah penghadaman dan membuang angin dalam badan?", options: ["A. Tongkat Ali", "B. Bunga Raya", "C. Halia", "D. Pegaga"], correctAnswer: "C", explanation: "Halia terbukti efektif melancarkan sistem pencernaan, mengurangkan loya dan 'membuang angin'." },
  { id: 1003, chapter: 10, question: "Ubat manakah yang dikelaskan sebagai Analgesik (penahan sakit) dalam perubatan moden?", options: ["A. Penisilin", "B. Parasetamol dan Aspirin", "C. Streptomisin", "D. Vaksin"], correctAnswer: "B", explanation: "Analgesik berfungsi mengurangkan rasa sakit dan menurunkan suhu badan (demam)." },
  { id: 1004, chapter: 10, question: "Apakah fungsi ubat jenis Antibiotik?", options: ["A. Membunuh virus yang menyebabkan selesema", "B. Merawat masalah mental (psikoteraputik)", "C. Membunuh atau merencatkan pertumbuhan bakteria penyebab penyakit", "D. Menahan kesakitan luka luar"], correctAnswer: "C", explanation: "Antibiotik (seperti Penisilin) hanya berkesan memusnahkan bakteria, ia TIDAK berkesan terhadap jangkitan virus." },
  { id: 1005, chapter: 10, question: "Mengapakah doktor sering mengingatkan pesakit supaya 'menghabiskan semua dos antibiotik' yang dipreskripsi walaupun pesakit sudah berasa sihat?", options: ["A. Supaya ubat tidak membazir", "B. Untuk mengelakkan bakteria menjadi kebal/rintang (antibiotic resistance) terhadap ubat tersebut", "C. Untuk menambah tenaga", "D. Kerana ubat akan luput"], correctAnswer: "B", explanation: "Jika dos tidak dihabiskan, baki bakteria yang tidak mati akan bermutasi dan menjadi lebih kuat (rintangan antibiotik)." },
  { id: 1006, chapter: 10, question: "Pesakit yang mengalami masalah kemurungan teruk atau skizofrenia akan diberikan ubat:", options: ["A. Antibiotik", "B. Psikoteraputik", "C. Analgesik", "D. Vitamin"], correctAnswer: "B", explanation: "Ubat psikoteraputik bertindak ke atas sistem saraf pusat otak dan harus diambil mengikut preskripsi yang sangat ketat." },
  { id: 1007, chapter: 10, question: "Perubatan Komplementari bertindak sebagai:", options: ["A. Rawatan alternatif untuk pesakit kanser yang menolak kimoterapi", "B. Pembedahan kosmetik", "C. Rawatan tambahan yang menyokong/bergabung dengan perubatan moden", "D. Rawatan sihir"], correctAnswer: "C", explanation: "Contohnya pesakit strok yang menjalani fisioterapi (moden) turut menjalani rawatan akupunktur (komplementari) untuk mempercepatkan pemulihan." },
  { id: 1008, chapter: 10, question: "Kaedah rawatan menusukkan jarum halus di titik meridian badan bertujuan memulihkan tenaga batin (Qi) dipanggil:", options: ["A. Kiropraktik", "B. Homeopati", "C. Urutan", "D. Akupunktur"], correctAnswer: "D", explanation: "Akupunktur ialah seni perubatan komplementari kuno dari China untuk merangsang sistem saraf dan melegakan kesakitan." },
  { id: 1009, chapter: 10, question: "Atom atau molekul yang kekurangan satu elektron pada petala terluarnya dipanggil:", options: ["A. Antioksida", "B. Radikal Bebas", "C. Ion penstabil", "D. Enzim"], correctAnswer: "B", explanation: "Kehilangan satu elektron menjadikan radikal bebas sangat tidak stabil dan reaktif, ia akan 'mencuri' elektron dari sel badan yang sihat." },
  { id: 1010, chapter: 10, question: "Pembentukan radikal bebas di dalam sel badan secara berlebihan boleh berpunca daripada faktor luaran (persekitaran). Antaranya ialah:", options: ["A. Tidur yang cukup", "B. Pendedahan kepada asap rokok, sinaran UV dan sisa toksik kilang", "C. Makan sayuran", "D. Minum air masak"], correctAnswer: "B", explanation: "Faktor seperti asap rokok dan radiasi mempercepatkan proses pengoksidaan yang menghasilkan lambakan radikal bebas." },
  { id: 1011, chapter: 10, question: "Apakah kesan bahaya radikal bebas ke atas tubuh manusia?", options: ["A. Menyebabkan rambut lebih hitam", "B. Menguatkan otot", "C. Merosakkan DNA sel yang membawa kepada kanser, penuaan awal dan penyakit kardiovaskular", "D. Mencegah demam denggi"], correctAnswer: "C", explanation: "Radikal bebas merosakkan membran sel dan rantaian DNA badan (tekanan oksidatif)." },
  { id: 1012, chapter: 10, question: "Bahan kimia yang bertindak melambatkan atau memberhentikan proses pengoksidaan akibat radikal bebas dipanggil:", options: ["A. Karsinogen", "B. Mutagen", "C. Antioksida", "D. Antibiotik"], correctAnswer: "C", explanation: "Antioksida meneutralkan radikal bebas dengan menderma elektronnya dengan sukarela tanpa menjadi tidak stabil." },
  { id: 1013, chapter: 10, question: "Buah limau, strawberi, dan kiwi mengandungi antioksida yang sangat popular iaitu:", options: ["A. Beta-karotena", "B. Lutein", "C. Vitamin C", "D. Likopena"], correctAnswer: "C", explanation: "Vitamin C adalah antioksida larut air yang penting untuk perlindungan sel dan sistem imun." },
  { id: 1014, chapter: 10, question: "Warna jingga/kuning pada lobak merah, betik dan ubi keledek berpunca daripada pigmen antioksida yang dikenali sebagai:", options: ["A. Likopena", "B. Beta-karotena", "C. Vitamin E", "D. Klorofil"], correctAnswer: "B", explanation: "Beta-karotena ditukar kepada Vitamin A di dalam badan yang baik untuk penglihatan." },
  { id: 1015, chapter: 10, question: "Antioksida Lutein sangat penting untuk kesihatan mata. Apakah sumber makanan kaya dengan lutein?", options: ["A. Susu", "B. Daging", "C. Sayur-sayuran hijau berdauan gelap (seperti bayam, brokoli)", "D. Roti"], correctAnswer: "C", explanation: "Lutein melindungi mata daripada kerosakan sinar biru matahari." },
  { id: 1016, chapter: 10, question: "Tomato dan buah tembikai mengandungi bahan antioksida warna merah yang dikenali sebagai:", options: ["A. Likopena", "B. Vitamin C", "C. Kolagen", "D. Sianida"], correctAnswer: "A", explanation: "Likopena sangat berkesan sebagai pencegah kanser prostat." },
  { id: 1017, chapter: 10, question: "Apakah tujuan 'Bahan Aktif' digunakan di dalam ubat dan makanan tambahan?", options: ["A. Hanya untuk perisa pewarna", "B. Komponen bahan kimia khusus yang memberikan kesan perubatan/teraputik merawat penyakit tertentu", "C. Untuk mengawet ubat", "D. Untuk mengeraskan pil"], correctAnswer: "B", explanation: "Setiap ubat mengandungi bahan aktif yang memainkan peranan menyembuhkan, contohnya parasetamol adalah bahan aktif untuk sakit kepala." },
  { id: 1018, chapter: 10, question: "Ginseng adalah akar herba tradisional. Apakah dakwaan kesan penggunaannya?", options: ["A. Melebatkan rambut", "B. Menambahkan tenaga, memulihkan stamina fizikal dan sistem imun badan", "C. Mengubati kanser tahap 4", "D. Membekukan darah"], correctAnswer: "B", explanation: "Ginseng dipercayai secara tradisional di Asia untuk membina kekuatan fizikal keseluruhan (tonik badan)." },
  { id: 1019, chapter: 10, question: "Mengapakah lidah buaya (Aloe Vera) banyak digunakan dalam perubatan tradisional untuk penjagaan kulit?", options: ["A. Ia bertindak sebagai antibiotik yang sangat kuat", "B. Lendir getahnya menyejukkan, meredakan lecur ringan ringan (sunburn) dan merawat luka kulit", "C. Ia mewarnakan kulit", "D. Ia memanaskan suhu badan"], correctAnswer: "B", explanation: "Aloe vera mengandungi bahan melembapkan dan antikeradangan untuk kerosakan epidermis luaran." },
  { id: 1020, chapter: 10, question: "Rawatan memanaskan dan meletakkan cawan kaca (yang divakumkan) pada permukaan kulit untuk mengeluarkan darah kotor dipanggil:", options: ["A. Akupunktur", "B. Kiropraktik", "C. Bekam (Cupping therapy)", "D. Homeopati"], correctAnswer: "C", explanation: "Terapi bekam dipercayai mengeluarkan toksin dan melancarkan peredaran darah mengikut amalan perubatan tradisional dan komplementari." },

  // BAB 11: Daya dan Gerakan
  { id: 1101, chapter: 11, question: "Dalam fizik, 'Jarak' didefinisikan sebagai:", options: ["A. Jarak terpendek yang menyambungkan titik mula dan akhir", "B. Panjang lintasan sebenar yang dilalui oleh objek", "C. Masa yang diambil untuk bergerak", "D. Kadar perubahan halaju"], correctAnswer: "B", explanation: "Jarak ialah kuantiti skalar (tiada arah spesifik) yang mengukur total perjalanan." },
  { id: 1102, chapter: 11, question: "Berbeza dengan Jarak, 'Sesaran' pula mengukur:", options: ["A. Jarak terpendek antara kedudukan awal dan akhir dalam arah tertentu", "B. Kelajuan objek", "C. Panjang pusingan kenderaan", "D. Daya tolakan"], correctAnswer: "A", explanation: "Sesaran ialah kuantiti vektor (mempunyai nilai dan arah), dilukis sebagai garis lurus dari titik Mula ke titik Tamat." },
  { id: 1103, chapter: 11, question: "Kadar perubahan jarak terhadap masa dipanggil:", options: ["A. Halaju", "B. Sesaran", "C. Laju", "D. Pecutan"], correctAnswer: "C", explanation: "Laju = Jarak / Masa." },
  { id: 1104, chapter: 11, question: "Kadar perubahan sesaran terhadap masa dipanggil:", options: ["A. Laju", "B. Halaju", "C. Jisim", "D. Pecutan"], correctAnswer: "B", explanation: "Halaju = Sesaran / Masa (memiliki arah yang spesifik seperti ke utara)." },
  { id: 1105, chapter: 11, question: "Sebuah kereta memecut dari kelajuan 0 m/s kepada 20 m/s dalam masa 5 saat. Berapakah nilai pecutannya?", options: ["A. 100 m/s²", "B. 25 m/s²", "C. 4 m/s²", "D. 15 m/s²"], correctAnswer: "C", explanation: "Pecutan = (Halaju Akhir - Halaju Awal) / Masa = (20 - 0) / 5 = 4 m/s²." },
  { id: 1106, chapter: 11, question: "Jika nilai pecutan sesuatu kenderaan ialah SIFAR (0 m/s²), ini bermakna:", options: ["A. Kenderaan itu berhenti", "B. Kenderaan itu bergerak ke belakang", "C. Kenderaan itu sedang bergerak dengan halaju malar (seragam)", "D. Kenderaan itu sedang terbang"], correctAnswer: "C", explanation: "Apabila halaju kenderaan sentiasa tetap (tidak bertambah laju atau brek), tiada perubahan halaju berlaku (Pecutan = 0)." },
  { id: 1107, chapter: 11, question: "Dalam Graf Sesaran-Masa, kecerunan (gradient) graf mewakili nilai apa?", options: ["A. Jisim", "B. Halaju", "C. Pecutan", "D. Daya"], correctAnswer: "B", explanation: "Kecerunan pada graf Sesaran-Masa ialah Sesaran dibahagi Masa, iaitu formula Halaju." },
  { id: 1108, chapter: 11, question: "Dalam Graf Halaju-Masa, apakah yang diwakili oleh kecerunan graf?", options: ["A. Sesaran", "B. Masa berlalu", "C. Jarak", "D. Pecutan"], correctAnswer: "D", explanation: "Perubahan halaju dibahagi perubahan masa pada paksi mewakili Pecutan." },
  { id: 1109, chapter: 11, question: "Luas di bawah graf Halaju-Masa boleh digunakan untuk mengira nilai:", options: ["A. Jisim", "B. Masa terbuang", "C. Sesaran/Jarak", "D. Daya"], correctAnswer: "C", explanation: "Mendarabkan halaju dan masa (luas bentuk segi tiga/segi empat di bawah graf) akan memberikan jarak yang dilalui kenderaan tersebut." },
  { id: 1110, chapter: 11, question: "Alat yang memplot titik pada pita kertas berkarbon untuk mengkaji corak pergerakan objek dalam makmal dikenali sebagai:", options: ["A. Oskiloskop", "B. Jangka masa detik (Ticker timer)", "C. Mikroskop", "D. Dinamometer"], correctAnswer: "B", explanation: "Jangka masa detik bergetar pada frekuensi 50Hz, meninggalkan 50 titik dalam masa 1 saat (setiap sela = 0.02 saat)." },
  { id: 1111, chapter: 11, question: "Jika titik-titik pada pita detik didapati semakin rapat antara satu sama lain, ini menunjukkan halaju troli sedang:", options: ["A. Menurun (Nyahpecutan)", "B. Bertambah (Memecut)", "C. Seragam (Malar)", "D. Sifar"], correctAnswer: "A", explanation: "Jarak antara titik mewakili jarak dilalui. Jarak mengecil bermaksud objek bergerak lebih perlahan dari sebelumnya." },
  { id: 1112, chapter: 11, question: "Jatuh bebas (free fall) berlaku apabila sebuah objek:", options: ["A. Dibuang dari kapal terbang", "B. Jatuh dan dipengaruhi daya tarikan graviti BUMI sahaja, tanpa sebarang rintangan udara", "C. Terapung dalam air", "D. Jatuh bersama payung terjun"], correctAnswer: "B", explanation: "Dalam situasi udara disedut keluar (vakum), sehelai pelepah dan sebiji bola besi yang dijatuhkan serentak akan tiba di lantai serentak." },
  { id: 1113, chapter: 11, question: "Berapakah nilai purata pecutan graviti (g) di permukaan Bumi?", options: ["A. 1.6 m/s²", "B. 5.5 m/s²", "C. 9.8 m/s² (atau 10 m/s²)", "D. 98 m/s²"], correctAnswer: "C", explanation: "Tindakan graviti Bumi menarik benda jatuh ke bawah dan memecutkannya pada kadar 9.8 meter sesaat setiap saat." },
  { id: 1114, chapter: 11, question: "Apakah yang dimaksudkan dengan 'Inersia'?", options: ["A. Sifat objek untuk mengubah arah pergerakannya", "B. Rintangan udara pada jasad", "C. Sifat semula jadi objek menentang sebarang perubahan kepada kedudukan asalnya, sama ada pegun atau bergerak", "D. Tarikan graviti antara planet"], correctAnswer: "C", explanation: "Sebab itulah badan kita terhumban ke depan secara tiba-tiba apabila kereta berhenti secara mengejut." },
  { id: 1115, chapter: 11, question: "Prinsip inersia adalah selari dengan undang-undang fizik mana?", options: ["A. Hukum Graviti Newton", "B. Hukum Gerakan Newton Pertama", "C. Hukum Termodinamik", "D. Prinsip Archimedes"], correctAnswer: "B", explanation: "Hukum Newton Pertama menyatakan 'Objek akan kekal pegun atau kekal bergerak lurus dengan halaju malar melainkan ditindakkan oleh suatu daya luar'." },
  { id: 1116, chapter: 11, question: "Inersia sesuatu objek bergantung secara langsung kepada:", options: ["A. Ketinggiannya", "B. Jisimnya", "C. Kelajuannya", "D. Isipadunya"], correctAnswer: "B", explanation: "Semakin besar jisim (berat) sesuatu objek, semakin besar inersianya, justeru sangat sukar untuk menghentikan lori balak berbanding motosikal." },
  { id: 1117, chapter: 11, question: "Ciri keselamatan manakah dalam kereta yang dipasang untuk mengurangkan kecederaan akibat kesan inersia kepada penumpang?", options: ["A. Lampu isyarat brek", "B. Tali pinggang keledar dan beg udara", "C. Radio", "D. Penyaman udara"], correctAnswer: "B", explanation: "Tali pinggang keledar menghalang penumpang (yang memiliki inersia nak terus bergerak) daripada melanggar cermin ketika kemalangan (brek kuat)." },
  { id: 1118, chapter: 11, question: "Aplikasi positif inersia dalam kehidupan harian ialah:", options: ["A. Memecahkan pintu yang terkunci", "B. Menghentak pemegang tukul secara menegak pada meja supaya kepala tukul keluli terpasang ketat", "C. Baling batu ke udara", "D. Bergolek di lantai"], correctAnswer: "B", explanation: "Kepala tukul keluli yang berat (inersia tinggi) akan terus bergerak ke bawah dan mengetatkan kayu tangkainya apabila tangkai tersebut dihentikan secara tiba-tiba di meja." },
  { id: 1119, chapter: 11, question: "Semasa bermain boling, mengapa bola yang berat sukar dilencongkan dan cenderung membelah pin?", options: ["A. Kerana ia mempunyai daya graviti", "B. Kerana jisimnya besar menyebabkan inersia pergerakannya tinggi (sukar ubah arah)", "C. Kerana bentuknya bulat", "D. Kerana pin ditarik oleh bola"], correctAnswer: "B", explanation: "Inersia tinggi memastikan bola terus mengekalkan laluannya ke depan walaupun melanggar rintangan kecil." },
  { id: 1120, chapter: 11, question: "Seekor kucing basah yang menggoncangkan badannya untuk mengeringkan bulu adalah menggunakan konsep:", options: ["A. Haba pendam", "B. Penyejatan", "C. Inersia", "D. Daya emparan"], correctAnswer: "C", explanation: "Titisan air kekal berinersia dan akan tercampak keluar dari bulu apabila badan kucing bertukar arah goncangan secara mendadak." },

  // BAB 12: Tenaga Nuklear
  { id: 1201, chapter: 12, question: "Apakah kebaikan utama menggunakan Tenaga Nuklear untuk menjana elektrik berbanding sumber bahan api fosil?", options: ["A. Ia amat murah dan mudah didapati", "B. Prosesnya tidak melepaskan gas rumah hijau seperti karbon dioksida", "C. Boleh dibuat di halaman rumah", "D. Sisa nuklear selamat diminum"], correctAnswer: "B", explanation: "Penjanaan tenaga nuklear tidak membakar hidrokarbon, jadi ia menyelesaikan masalah perubahan iklim/pemanasan global dengan tidak membebaskan gas tercemar." },
  { id: 1202, chapter: 12, question: "Bahan api radioaktif utama yang digunakan dalam kebanyakan reaktor tenaga nuklear di dunia ialah:", options: ["A. Karbon-14", "B. Besi-56", "C. Uranium-235", "D. Radium-226"], correctAnswer: "C", explanation: "Isotop Uranium-235 mudah dipisahkan/dibelah nukleusnya dan menghasilkan tenaga yang stabil." },
  { id: 1203, chapter: 12, question: "Terdapat dua proses tindak balas nuklear. Proses membelah satu nukleus berat yang tidak stabil menjadi nukleus yang lebih ringan dikenali sebagai:", options: ["A. Pelakuran Nukleus", "B. Pembelahan Nukleus (Nuclear Fission)", "C. Fotosintesis", "D. Pencernaan"], correctAnswer: "B", explanation: "Apabila satu neutron dibedil kepada nukleus Uranium-235, ia berpecah, membebaskan tenaga haba yang besar serta lebih banyak neutron." },
  { id: 1204, chapter: 12, question: "Pembelahan satu nukleus Uranium akan membebaskan kira-kira 3 neutron tambahan. Neutron baharu ini pula akan melanggar dan membelah atom Uranium yang lain secara berterusan. Proses ini dipanggil:", options: ["A. Kitar Semula", "B. Tindak Balas Berantai (Chain Reaction)", "C. Reaksi Pembakaran", "D. Radioterapi"], correctAnswer: "B", explanation: "Tindak balas berantai ini dimanfaatkan dalam reaktor nuklear (secara terkawal) dan bom atom (tanpa kawalan)." },
  { id: 1205, chapter: 12, question: "Proses Pelakuran Nukleus (Nuclear Fusion) pula merujuk kepada:", options: ["A. Pemecahan nukleus", "B. Penggabungan dua nukleus ringan membentuk satu nukleus berat", "C. Pendidihan air berat", "D. Pemusnahan elektron"], correctAnswer: "B", explanation: "Isotop hidrogen ringan (Deuterium dan Tritium) akan berlanggar untuk bercantum, melepaskan tenaga yang jauh lebih besar." },
  { id: 1206, chapter: 12, question: "Proses Pelakuran Nukleus berlaku secara semula jadi dan membekalkan haba serta cahaya di:", options: ["A. Dalam perut bumi (Gunung Berapi)", "B. Loji Tenaga Arang Batu", "C. Teras Matahari dan bintang-bintang", "D. Bulan"], correctAnswer: "C", explanation: "Tekanan dan haba yang terlampau dahsyat di matahari menyediakan syarat membolehkan atom hidrogen bercantum." },
  { id: 1207, chapter: 12, question: "Apakah fungsi utama 'Rod Pengawal' (Control Rods) di dalam sebuah reaktor nuklear stesen janakuasa?", options: ["A. Memanaskan air", "B. Memutar turbin elektrik", "C. Menyerap neutron tambahan untuk mengawal kadar tindak balas berantai", "D. Menambah bahan api Uranium"], correctAnswer: "C", explanation: "Bahan seperti Boron atau Kadmium dimasukkan untuk menghisap neutron lebihan agar loji tidak mengalami peleburan melampau (meltdown)." },
  { id: 1208, chapter: 12, question: "Apakah peranan konkrit tebal yang meliputi teras reaktor nuklear?", options: ["A. Mengurangkan kos binaan bangunan", "B. Menghalang penceroboh mencuri bahan api", "C. Berfungsi sebagai perisai biologi untuk menghalang sinaran radioaktif yang sangat berbahaya daripada terlepas ke persekitaran", "D. Memantulkan bunyi bising"], correctAnswer: "C", explanation: "Konkrit tebal yang dicampur plumbum menghalang sinaran Gamma dan kebocoran neutron." },
  { id: 1209, chapter: 12, question: "Bagaimanakah tenaga elektrik dijana dalam sesebuah loji janakuasa nuklear?", options: ["A. Elektrik dipancar terus dari radioaktif", "B. Haba tindak balas nuklear mendidihkan air menjadi stim bertekanan tinggi yang kemudiannya memutarkan turbin dinamo elektrik", "C. Pembakaran uranium mengeluarkan asap yang bertukar jadi elektrik", "D. Cahaya dari uranium ditangkap panel solar"], correctAnswer: "B", explanation: "Secara asasnya sistem ini sama seperti loji arang batu, tetapi tenaga pembakaran digantikan dengan tenaga haba dari pemisahan atom nukleus." },
  { id: 1210, chapter: 12, question: "Masalah utama dengan industri tenaga nuklear yang ditakuti ramai ialah:", options: ["A. Mengurangkan peluang pekerjaan", "B. Pengurusan sisa radioaktif yang mempunyai separuh hayat beribu-ribu tahun dan kemalangan kebocoran reaktor", "C. Sering terpadam", "D. Terlalu banyak bekalan elektrik"], correctAnswer: "B", explanation: "Sisa nuklear (nuclear waste) tidak boleh diuraikan dengan mudah, ia mesti ditanam jauh di dalam kerak bumi yang stabil berpuluh ribu tahun lamanya." },
  { id: 1211, chapter: 12, question: "Kemalangan loji nuklear bersejarah Chernobyl (1986) dan Fukushima (2011) mendedahkan rakyat kepada kesan radiasi akut. Apakah simptom segera (jangka pendek) kepada pendedahan tersebut?", options: ["A. Kanser dalam masa 1 jam", "B. Loya, muntah berdarah, dan keguguran rambut secara mendadak akibat pemusnahan sel darah putih", "C. Berubah menjadi wira adiwira (superhero)", "D. Buta warna"], correctAnswer: "B", explanation: "Sinaran tahap ekstrem yang membunuh sel dipanggil 'Penyakit Sinaran Akut' (Acute Radiation Sickness)." },
  { id: 1212, chapter: 12, question: "Kesan jangka panjang pendedahan radioaktif pada hidupan (flora/fauna dan manusia) ialah:", options: ["A. Pertumbuhan gigi berlebihan", "B. Memanjangkan jangka hayat makhluk", "C. Mutasi gen dan kromosom yang mencetuskan kanser (seperti leukemia) dan kecacatan janin", "D. Kulit menjadi putih"], correctAnswer: "C", explanation: "Radiasi menghancurkan rantai molekul asid nukleik (DNA), menukar kod genetik biologi hidupan secara kekal." },
  { id: 1213, chapter: 12, question: "Agensi antarabangsa yang dipertanggungjawabkan untuk memantau keselamatan dan menyelia penggunaan tenaga nuklear bagi tujuan aman di seluruh dunia ialah:", options: ["A. Pertubuhan Kesihatan Sedunia (WHO)", "B. Agensi Tenaga Atom Antarabangsa (IAEA)", "C. Bank Dunia (World Bank)", "D. Pertubuhan Perdagangan Dunia (WTO)"], correctAnswer: "B", explanation: "IAEA memeriksa loji seluruh dunia untuk memastikan material nuklear tidak dialihkan menjadi senjata nuklear (bom atom)." },
  { id: 1214, chapter: 12, question: "Bahan yang digunakan sebagai 'Moderator' dalam reaktor nuklear (untuk memperlahankan pergerakan neutron supaya mudah diserap Uranium) kebiasaannya ialah:", options: ["A. Gas oksigen", "B. Karbon (Grafit) atau Air biasa (Light Water)", "C. Emas", "D. Gas klorin"], correctAnswer: "B", explanation: "Air atau batu grafit tidak menyerap neutron sebaliknya memantul dan memperlahankan neutron seperti perlanggaran bola billiard." },
  { id: 1215, chapter: 12, question: "Tenaga yang dibebaskan daripada tindak balas nuklear (berbanding pembakaran arang batu) adalah:", options: ["A. Sama besar dengan 1kg arang batu", "B. Berjuta-juta kali ganda lebih besar berbanding pembakaran kuantiti yang sama bahan api fosil", "C. Lebih kecil tetapi lebih murah", "D. Tidak menghasilkan sebarang haba"], correctAnswer: "B", explanation: "1 kilogram Uranium-235 boleh menghasilkan tenaga setara pembakaran 3 juta kilogram arang batu." },
  { id: 1216, chapter: 12, question: "Sisa radioaktif berkeaktifan rendah (Low-level waste) seperti pakaian kerja makmal loji dilupuskan dengan cara:", options: ["A. Ditanam di tong sampah biasa", "B. Dihantar ke matahari dengan roket", "C. Dimampatkan dan disimpan dalam dram keluli dan ditanam di fasiliti khas yang cetek", "D. Dibakar secara terbuka"], correctAnswer: "C", explanation: "Bahan ini cepat memudar ke tahap selamat (beberapa tahun/dekad)." },
  { id: 1217, chapter: 12, question: "Sisa bahan api Uranium yang sudah haus (High-level waste) dilupuskan di dalam:", options: ["A. Lautan dalam", "B. Kolam simpanan air di loji, kemudian dialihkan ke dalam simpanan pelindung kering (dry cask) dan ditanam di lubang galian geologi dalam (Deep Geological Repositories)", "C. Sungai awam", "D. Di bawah tapak rumah"], correctAnswer: "B", explanation: "Galian geologi (batu garam purba dll) bawah tanah beratus meter bertujuan mengelakkan sisa tersentuh dengan sumber air minuman selagi ia membahayakan (10,000+ tahun)." },
  { id: 1218, chapter: 12, question: "Hukum Albert Einstein yang menjelaskan perkaitan antara jisim yang 'hilang' dalam tindak balas nuklear dan letupan tenaga besar ialah:", options: ["A. F = ma", "B. E = mc²", "C. V = IR", "D. Hukum Ohm"], correctAnswer: "B", explanation: "Sedikit kehilangan jisim (mass defect) bertukar menjadi Tenaga (E) didarab dengan Halaju Cahaya Kuasa Dua (mc²), menyebabkan nilai E sangat gergasi." },
  { id: 1219, chapter: 12, question: "Senjata nuklear (bom atom) yang dilepaskan di Hiroshima dan Nagasaki semasa Perang Dunia Kedua beroperasi berdasarkan prinsip:", options: ["A. Pelakuran nukleus (seperti matahari)", "B. Pembelahan nukleus tanpa kawalan", "C. Pembakaran kimia karbon", "D. Elektromagnetik"], correctAnswer: "B", explanation: "Bom uranium (Little Boy) dipicu menghasilkan tindak balas berantai yang tidak mempunyai mekanisma pengawal, sekaligus melepaskan ke semua habanya serentak (letupan)." },
  { id: 1220, chapter: 12, question: "Walaupun dikritik, loji tenaga nuklear sangat relevan bagi negara yang:", options: ["A. Banyak kawasan lapang gurun", "B. Mempunyai sumber minyak petrol yang melimpah ruah", "C. Kekurangan sumber asli bumi (seperti Jepun) untuk memenuhi permintaan elektrik industrinya yang tinggi", "D. Mengalami cuaca ribut pasir"], correctAnswer: "C", explanation: "Negara industri maju tetapi tiada sumber mineral sering bergantung kepada loji nuklear untuk menjamin kestabilan bekalan elektrik domestiknya tanpa bergantung pada import bahan bakar." }

];
